{
  "name": "BinauralForge",
  "description": "A professional-grade web editor for binaural beats, compatible with SBaGen-style scripts. Features real-time synthesis, visual timeline editing, and script manipulation."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
