export interface BeatEvent {
  id: string;
  timeOffset: number; // in seconds
  carrierFreq: number; // Hz
  beatFreq: number; // Hz
  volume: number; // 0-100
  fadeType?: 'linear' | 'exponential';
}

export interface PlaybackState {
  isPlaying: boolean;
  currentTime: number; // seconds
  totalDuration: number; // seconds
  analyserDataLeft: Uint8Array;
  analyserDataRight: Uint8Array;
}

export enum ViewMode {
  TIMELINE = 'TIMELINE',
  SCRIPT = 'SCRIPT',
}

import { BeatEvent } from '../types';

// Simplified SBaGen parser logic
// Format usually: HH:MM channel: carrier+beat/vol
// We will support a simplified subset: "MM:SS carrier+beat/vol" for this MVP

export const parseScript = (script: string): BeatEvent[] => {
  const lines = script.split('\n');
  const events: BeatEvent[] = [];
  let idCounter = 0;

  lines.forEach((line) => {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#')) return;

    // Regex to match "MM:SS carrier+beat/vol" or "HH:MM:SS ..."
    // Example: 00:00 200+10/50
    const match = trimmed.match(/(\d{1,2}):(\d{2})(?::(\d{2}))?\s+([\d.]+)\+([\d.]+)\/([\d.]+)/);

    if (match) {
      let hours = 0, minutes = 0, seconds = 0;

      // Heuristic to detect format MM:SS vs HH:MM:SS
      if (match[3]) {
        hours = parseInt(match[1], 10);
        minutes = parseInt(match[2], 10);
        seconds = parseInt(match[3], 10);
      } else {
        minutes = parseInt(match[1], 10);
        seconds = parseInt(match[2], 10);
      }

      const totalSeconds = hours * 3600 + minutes * 60 + seconds;
      const carrier = parseFloat(match[4] || match[3] || '0'); // Index shift depends on regex capture
      const beat = parseFloat(match[5] || match[4] || '0');
      const vol = parseFloat(match[6] || match[5] || '0');

      events.push({
        id: `evt_${idCounter++}_${Date.now()}`,
        timeOffset: totalSeconds,
        carrierFreq: carrier,
        beatFreq: beat,
        volume: vol,
      });
    }
  });

  return events.sort((a, b) => a.timeOffset - b.timeOffset);
};

export const generateScript = (events: BeatEvent[]): string => {
  let script = "# Generated by BinauralForge\n# Time Carrier+Beat/Volume\n\n";

  events.forEach(evt => {
    const mins = Math.floor(evt.timeOffset / 60);
    const secs = Math.floor(evt.timeOffset % 60);
    const timeStr = `${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;

    script += `${timeStr} ${evt.carrierFreq.toFixed(1)}+${evt.beatFreq.toFixed(2)}/${evt.volume.toFixed(1)}\n`;
  });

  return script;
};

import { BeatEvent } from '../types';

class BinauralAudioEngine {
  private ctx: AudioContext | null = null;
  private masterGain: GainNode | null = null;

  // Left Channel
  private oscLeft: OscillatorNode | null = null;
  private pannerLeft: StereoPannerNode | null = null;

  // Right Channel
  private oscRight: OscillatorNode | null = null;
  private pannerRight: StereoPannerNode | null = null;

  // Analysis
  public analyserLeft: AnalyserNode | null = null;
  public analyserRight: AnalyserNode | null = null;

  private isRunning: boolean = false;
  private events: BeatEvent[] = [];
  private playbackStartTime: number = 0;
  private pausedAt: number = 0;

  constructor() {
    // Lazy initialization in init() to respect browser autoplay policies
  }

  init() {
    if (this.ctx) return;
    this.ctx = new (window.AudioContext || (window as any).webkitAudioContext)();
    this.masterGain = this.ctx.createGain();
    this.masterGain.connect(this.ctx.destination);
    this.masterGain.gain.value = 0.5; // Master Volume

    this.analyserLeft = this.ctx.createAnalyser();
    this.analyserRight = this.ctx.createAnalyser();
    this.analyserLeft.fftSize = 256;
    this.analyserRight.fftSize = 256;
  }

  private createOscillators(startTime: number) {
    if (!this.ctx || !this.masterGain) return;

    // Left Ear (Carrier + Beat/2)
    // Actually, traditionally: Left = Carrier - Beat/2, Right = Carrier + Beat/2
    // Or simpler: Left = Carrier, Right = Carrier + Beat
    // Let's go with symmetrical: L = C - B/2, R = C + B/2 for centered perception.

    this.oscLeft = this.ctx.createOscillator();
    this.oscLeft.type = 'sine';
    this.pannerLeft = this.ctx.createStereoPanner();
    this.pannerLeft.pan.value = -1; // Full Left

    this.oscRight = this.ctx.createOscillator();
    this.oscRight.type = 'sine';
    this.pannerRight = this.ctx.createStereoPanner();
    this.pannerRight.pan.value = 1; // Full Right

    // Routing
    this.oscLeft.connect(this.pannerLeft);
    if(this.analyserLeft) this.pannerLeft.connect(this.analyserLeft);
    this.pannerLeft.connect(this.masterGain);

    this.oscRight.connect(this.pannerRight);
    if(this.analyserRight) this.pannerRight.connect(this.analyserRight);
    this.pannerRight.connect(this.masterGain);

    // Schedule Values based on Events
    // To handle "seeking" or "starting mid-way", we need to schedule from 'startTime' relative to ctx.currentTime
    const now = this.ctx.currentTime;

    this.events.forEach((evt, index) => {
      const nextEvt = this.events[index + 1];
      const evtTime = now + (evt.timeOffset - this.pausedAt); // Calculate absolute audio time

      if (evtTime < now && (!nextEvt || (now + (nextEvt.timeOffset - this.pausedAt)) < now)) {
         // Event completely in the past, ignore or set initial value if it's the last past one
         return; 
      }

      // Determine effective start time for this parameter ramp
      // If the event is in the past but the *next* is in the future, we need to interpolate start values
      // For simplicity in this engine, we will just schedule ramps linearly.
      // A robust engine requires calculating the interpolated value at 'now' if we start in middle of segment.

      const leftFreq = evt.carrierFreq - (evt.beatFreq / 2);
      const rightFreq = evt.carrierFreq + (evt.beatFreq / 2);

      // Using linearRampToValueAtTime is tricky if the start time is in the past.
      // We will use setValueAtTime.

      if (evtTime >= now) {
         this.oscLeft?.frequency.linearRampToValueAtTime(leftFreq, evtTime);
         this.oscRight?.frequency.linearRampToValueAtTime(rightFreq, evtTime);
         // Volume control could be added per oscillator or master, simpler to keep master constant for now or modulate gain
      } else {
         // Immediate set for passed events (or initial state)
         this.oscLeft?.frequency.setValueAtTime(leftFreq, now);
         this.oscRight?.frequency.setValueAtTime(rightFreq, now);
      }
    });

    this.oscLeft.start(now);
    this.oscRight.start(now);
  }

  loadEvents(events: BeatEvent[]) {
    this.events = events;
  }

  play(offset: number = 0) {
    if (!this.ctx) this.init();
    if (this.isRunning) this.stop();
    if (this.ctx?.state === 'suspended') this.ctx.resume();

    this.pausedAt = offset;
    this.createOscillators(offset);
    this.isRunning = true;
    this.playbackStartTime = this.ctx!.currentTime - offset;
  }

  stop() {
    if (this.oscLeft) {
      try { this.oscLeft.stop(); } catch(e) {}
      this.oscLeft.disconnect();
      this.oscLeft = null;
    }
    if (this.oscRight) {
      try { this.oscRight.stop(); } catch(e) {}
      this.oscRight.disconnect();
      this.oscRight = null;
    }
    this.isRunning = false;
  }

  getCurrentTime(): number {
    if (!this.isRunning || !this.ctx) return this.pausedAt;
    return this.ctx.currentTime - this.playbackStartTime;
  }
}

export const audioEngine = new BinauralAudioEngine();

import React, { useEffect, useRef } from 'react';
import { audioEngine } from '../services/audioEngine';

export const Visualizer: React.FC<{ isPlaying: boolean }> = ({ isPlaying }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    if (!isPlaying) return;

    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    let animationId: number;
    const bufferLength = audioEngine.analyserLeft?.frequencyBinCount || 128;
    const dataArrayL = new Uint8Array(bufferLength);
    const dataArrayR = new Uint8Array(bufferLength);

    const draw = () => {
      if (!audioEngine.analyserLeft || !audioEngine.analyserRight) return;

      audioEngine.analyserLeft.getByteTimeDomainData(dataArrayL);
      audioEngine.analyserRight.getByteTimeDomainData(dataArrayR);

      ctx.fillStyle = '#0d1117';
      ctx.fillRect(0, 0, canvas.width, canvas.height);

      ctx.lineWidth = 2;

      // Draw Left Channel (Cyan)
      ctx.strokeStyle = '#22d3ee'; // Cyan 400
      ctx.beginPath();
      const sliceWidth = canvas.width * 1.0 / bufferLength;
      let x = 0;
      for (let i = 0; i < bufferLength; i++) {
        const v = dataArrayL[i] / 128.0;
        const y = v * (canvas.height / 2); // Top half
        if (i === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
        x += sliceWidth;
      }
      ctx.stroke();

      // Draw Right Channel (Magenta)
      ctx.strokeStyle = '#e879f9'; // Fuchsia 400
      ctx.beginPath();
      x = 0;
      for (let i = 0; i < bufferLength; i++) {
        const v = dataArrayR[i] / 128.0;
        const y = (v * (canvas.height / 2)) + (canvas.height / 2) - (canvas.height / 4); // Offset to be visible distinct from top
        // Actually, let's overlap them centered
        const yCentered = (v * (canvas.height / 2)) + (canvas.height / 4);

        if (i === 0) ctx.moveTo(x, yCentered);
        else ctx.lineTo(x, yCentered);
        x += sliceWidth;
      }
      ctx.stroke();

      animationId = requestAnimationFrame(draw);
    };

    draw();

    return () => cancelAnimationFrame(animationId);
  }, [isPlaying]);

  return (
    <div className="w-full h-32 bg-gray-900 rounded-lg overflow-hidden border border-gray-700 shadow-inner relative">
       {!isPlaying && <div className="absolute inset-0 flex items-center justify-center text-gray-600 font-mono text-sm">Visualizer Idle</div>}
      <canvas ref={canvasRef} width={600} height={128} className="w-full h-full block" />
    </div>
  );
};

import React, { useMemo } from 'react';
import { BeatEvent } from '../types';
import { Trash2, Edit } from 'lucide-react';

interface TimelineProps {
  events: BeatEvent[];
  duration: number;
  onEventClick: (event: BeatEvent) => void;
  onDeleteEvent: (id: string) => void;
  playbackTime: number;
}

export const Timeline: React.FC<TimelineProps> = ({ events, duration, onEventClick, onDeleteEvent, playbackTime }) => {
  const widthPercent = (time: number) => (time / duration) * 100;

  // Calculate segments between events
  const segments = useMemo(() => {
    if (events.length < 2) return [];
    const segs = [];
    for (let i = 0; i < events.length - 1; i++) {
      const start = events[i];
      const end = events[i+1];
      segs.push({ start, end });
    }
    return segs;
  }, [events]);

  return (
    <div className="relative w-full h-48 bg-gray-850 border border-gray-700 rounded-lg overflow-hidden select-none">
      {/* Grid Lines */}
      <div className="absolute inset-0 flex pointer-events-none opacity-20">
        {[...Array(10)].map((_, i) => (
          <div key={i} className="flex-1 border-r border-gray-500 h-full"></div>
        ))}
      </div>

      {/* Playhead */}
      <div 
        className="absolute top-0 bottom-0 w-0.5 bg-red-500 z-30 transition-all duration-75 ease-linear"
        style={{ left: `${widthPercent(playbackTime)}%` }}
      >
        <div className="w-2 h-2 bg-red-500 rounded-full -ml-[3px] -mt-1 shadow-glow" />
      </div>

      {/* Segments (Gradients) */}
      {segments.map((seg, idx) => (
        <div
          key={`seg-${seg.start.id}`}
          className="absolute top-8 bottom-8 bg-gradient-to-r from-accent-600/30 to-accent-600/30 border-t border-b border-accent-500/50"
          style={{
            left: `${widthPercent(seg.start.timeOffset)}%`,
            width: `${widthPercent(seg.end.timeOffset - seg.start.timeOffset)}%`
          }}
        >
          <div className="absolute inset-0 flex items-center justify-center text-[10px] text-accent-200 font-mono opacity-0 hover:opacity-100 transition-opacity">
            {seg.start.beatFreq}Hz &rarr; {seg.end.beatFreq}Hz
          </div>
        </div>
      ))}

      {/* Event Points */}
      {events.map((evt) => (
        <div
          key={evt.id}
          className="absolute top-0 bottom-0 w-0.5 group z-20"
          style={{ left: `${widthPercent(evt.timeOffset)}%` }}
        >
          {/* Vertical Line */}
          <div className="h-full w-full bg-gray-500/50 group-hover:bg-white/50 transition-colors"></div>

          {/* Handle */}
          <div 
            className="absolute top-1/2 -mt-3 -ml-[5px] w-[11px] h-[24px] bg-gray-200 rounded-sm shadow cursor-pointer hover:bg-white hover:scale-110 transition-all flex items-center justify-center z-20"
            onClick={() => onEventClick(evt)}
          >
            <div className="w-0.5 h-3 bg-gray-400"></div>
          </div>

          {/* Tooltip / Actions */}
          <div className="absolute bottom-2 left-2 bg-gray-800 p-2 rounded shadow-xl border border-gray-700 hidden group-hover:flex flex-col gap-1 z-50 w-32">
            <div className="text-xs font-mono text-gray-300">
              T: {evt.timeOffset}s<br/>
              C: {evt.carrierFreq}Hz<br/>
              B: {evt.beatFreq}Hz
            </div>
            <div className="flex gap-2 mt-1">
               <button onClick={(e) => { e.stopPropagation(); onEventClick(evt); }} className="p-1 bg-blue-600 rounded hover:bg-blue-500">
                  <Edit size={12} />
               </button>
               <button onClick={(e) => { e.stopPropagation(); onDeleteEvent(evt.id); }} className="p-1 bg-red-600 rounded hover:bg-red-500">
                  <Trash2 size={12} />
               </button>
            </div>
          </div>
        </div>
      ))}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { BeatEvent } from '../types';
import { X, Check } from 'lucide-react';

interface EventEditorProps {
  event: BeatEvent | null;
  onSave: (event: BeatEvent) => void;
  onCancel: () => void;
}

export const EventEditor: React.FC<EventEditorProps> = ({ event, onSave, onCancel }) => {
  const [formData, setFormData] = useState<BeatEvent | null>(null);

  useEffect(() => {
    setFormData(event);
  }, [event]);

  if (!formData || !event) return null;

  const handleChange = (field: keyof BeatEvent, value: string) => {
    setFormData({
      ...formData,
      [field]: parseFloat(value) || 0
    });
  };

  return (
    <div className="fixed inset-0 bg-black/50 backdrop-blur-sm z-50 flex items-center justify-center p-4">
      <div className="bg-gray-800 border border-gray-700 rounded-xl shadow-2xl p-6 w-full max-w-md animate-in fade-in zoom-in duration-200">
        <div className="flex justify-between items-center mb-6">
          <h2 className="text-xl font-semibold text-white">Edit Event</h2>
          <button onClick={onCancel} className="text-gray-400 hover:text-white transition-colors">
            <X size={20} />
          </button>
        </div>

        <div className="space-y-4">
          <div>
            <label className="block text-xs font-medium text-gray-400 uppercase tracking-wider mb-1">Time Offset (sec)</label>
            <input 
              type="number" 
              value={formData.timeOffset} 
              onChange={(e) => handleChange('timeOffset', e.target.value)}
              className="w-full bg-gray-900 border border-gray-700 rounded p-2 text-white focus:ring-2 focus:ring-accent-500 outline-none"
            />
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-xs font-medium text-gray-400 uppercase tracking-wider mb-1">Carrier Freq (Hz)</label>
              <input 
                type="number" 
                value={formData.carrierFreq} 
                onChange={(e) => handleChange('carrierFreq', e.target.value)}
                className="w-full bg-gray-900 border border-gray-700 rounded p-2 text-white focus:ring-2 focus:ring-accent-500 outline-none"
              />
            </div>
            <div>
              <label className="block text-xs font-medium text-gray-400 uppercase tracking-wider mb-1">Beat Freq (Hz)</label>
              <input 
                type="number" 
                step="0.1"
                value={formData.beatFreq} 
                onChange={(e) => handleChange('beatFreq', e.target.value)}
                className="w-full bg-gray-900 border border-gray-700 rounded p-2 text-white focus:ring-2 focus:ring-accent-500 outline-none"
              />
            </div>
          </div>

          <div>
             <label className="block text-xs font-medium text-gray-400 uppercase tracking-wider mb-1">Volume (0-100)</label>
             <input 
                type="range" 
                min="0" 
                max="100" 
                value={formData.volume} 
                onChange={(e) => handleChange('volume', e.target.value)}
                className="w-full accent-accent-500"
              />
              <div className="text-right text-xs text-gray-500 mt-1">{formData.volume}%</div>
          </div>
        </div>

        <div className="mt-8 flex gap-3">
          <button 
            onClick={() => onSave(formData)}
            className="flex-1 bg-accent-600 hover:bg-accent-500 text-white py-2 rounded font-medium flex items-center justify-center gap-2 transition-colors"
          >
            <Check size={18} /> Save Changes
          </button>
          <button 
            onClick={onCancel}
            className="flex-1 bg-gray-700 hover:bg-gray-600 text-white py-2 rounded font-medium transition-colors"
          >
            Cancel
          </button>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { 
  Play, Pause, Download, Upload, Plus, FileCode, Activity, Music, 
  Settings, Volume2, Save
} from 'lucide-react';
import { BeatEvent, ViewMode } from './types';
import { parseScript, generateScript } from './services/parser';
import { audioEngine } from './services/audioEngine';
import { Timeline } from './components/Timeline';
import { Visualizer } from './components/Visualizer';
import { EventEditor } from './components/EventEditor';

const DEFAULT_SCRIPT = `# Example Binaural Session
# Time  Carrier+Beat/Volume
00:00 200+10/50
01:00 200+8/50
05:00 150+4/60
10:00 150+4/0
`;

function App() {
  const [script, setScript] = useState<string>(DEFAULT_SCRIPT);
  const [events, setEvents] = useState<BeatEvent[]>([]);
  const [isPlaying, setIsPlaying] = useState(false);
  const [viewMode, setViewMode] = useState<ViewMode>(ViewMode.TIMELINE);
  const [currentTime, setCurrentTime] = useState(0);
  const [editingEvent, setEditingEvent] = useState<BeatEvent | null>(null);

  // Ref for requestAnimationFrame to update UI during playback
  const rafRef = useRef<number>();

  // Parse script on load and when changed (debounce could be added)
  useEffect(() => {
    const newEvents = parseScript(script);
    setEvents(newEvents);
    audioEngine.loadEvents(newEvents);
  }, [script]);

  // Update script when events change via GUI
  const updateScriptFromEvents = (newEvents: BeatEvent[]) => {
    setEvents(newEvents);
    setScript(generateScript(newEvents));
    audioEngine.loadEvents(newEvents);
  };

  const handlePlayToggle = () => {
    if (isPlaying) {
      audioEngine.stop();
      setIsPlaying(false);
      cancelAnimationFrame(rafRef.current!);
    } else {
      audioEngine.play(currentTime);
      setIsPlaying(true);

      const updateLoop = () => {
        setCurrentTime(audioEngine.getCurrentTime());
        rafRef.current = requestAnimationFrame(updateLoop);
      };
      updateLoop();
    }
  };

  const handleSeek = (e: React.ChangeEvent<HTMLInputElement>) => {
    const time = parseFloat(e.target.value);
    setCurrentTime(time);
    if (isPlaying) {
       audioEngine.play(time); // Re-trigger play from new time
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (evt) => {
      const content = evt.target?.result as string;
      setScript(content);
    };
    reader.readAsText(file);
  };

  const handleDownload = () => {
    const blob = new Blob([script], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'binaural_session.sbg';
    a.click();
    URL.revokeObjectURL(url);
  };

  const handleAddEvent = () => {
    const lastEvent = events[events.length - 1];
    const newTime = lastEvent ? lastEvent.timeOffset + 60 : 0;
    const newEvent: BeatEvent = {
      id: `evt_${Date.now()}`,
      timeOffset: newTime,
      carrierFreq: lastEvent?.carrierFreq || 200,
      beatFreq: lastEvent?.beatFreq || 10,
      volume: lastEvent?.volume || 50
    };
    updateScriptFromEvents([...events, newEvent]);
    setEditingEvent(newEvent);
  };

  const handleEventUpdate = (updated: BeatEvent) => {
    const newEvents = events.map(e => e.id === updated.id ? updated : e).sort((a,b) => a.timeOffset - b.timeOffset);
    updateScriptFromEvents(newEvents);
    setEditingEvent(null);
  };

  const handleDeleteEvent = (id: string) => {
    const newEvents = events.filter(e => e.id !== id);
    updateScriptFromEvents(newEvents);
  };

  const totalDuration = events.length > 0 ? events[events.length - 1].timeOffset + 60 : 600;

  return (
    <div className="min-h-screen bg-gray-950 text-gray-200 font-sans flex flex-col">
      {/* Header */}
      <header className="bg-gray-900 border-b border-gray-800 p-4 flex items-center justify-between sticky top-0 z-40">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 bg-accent-600 rounded-lg flex items-center justify-center shadow-lg shadow-accent-900/50">
             <Activity className="text-white" />
          </div>
          <div>
            <h1 className="text-xl font-bold text-white tracking-tight">BinauralForge</h1>
            <p className="text-xs text-gray-500 font-mono">SBaGen Compatible Editor</p>
          </div>
        </div>

        <div className="flex items-center gap-4">
           {/* Toolbar */}
           <div className="flex bg-gray-800 rounded-lg p-1 border border-gray-700">
             <button 
                onClick={() => setViewMode(ViewMode.TIMELINE)}
                className={`p-2 rounded ${viewMode === ViewMode.TIMELINE ? 'bg-gray-700 text-white' : 'text-gray-400 hover:text-white'}`}
                title="Timeline View"
             >
                <Music size={18} />
             </button>
             <button 
                onClick={() => setViewMode(ViewMode.SCRIPT)}
                className={`p-2 rounded ${viewMode === ViewMode.SCRIPT ? 'bg-gray-700 text-white' : 'text-gray-400 hover:text-white'}`}
                title="Script View"
             >
                <FileCode size={18} />
             </button>
           </div>

           <div className="h-6 w-px bg-gray-800 mx-2" />

           <label className="cursor-pointer bg-gray-800 hover:bg-gray-700 text-gray-300 px-3 py-2 rounded border border-gray-700 transition-colors flex items-center gap-2 text-sm">
             <Upload size={16} />
             <span>Load</span>
             <input type="file" className="hidden" accept=".sbg,.txt" onChange={handleFileUpload} />
           </label>

           <button 
              onClick={handleDownload}
              className="bg-gray-800 hover:bg-gray-700 text-gray-300 px-3 py-2 rounded border border-gray-700 transition-colors flex items-center gap-2 text-sm"
           >
             <Save size={16} />
