import React, { useMemo } from 'react';
import { BeatEvent } from '../types';
import { Trash2, Edit } from 'lucide-react';

interface TimelineProps {
  events: BeatEvent[];
  duration: number;
  onEventClick: (event: BeatEvent) => void;
  onDeleteEvent: (id: string) => void;
  playbackTime: number;
}

export const Timeline: React.FC<TimelineProps> = ({ events, duration, onEventClick, onDeleteEvent, playbackTime }) => {
  const widthPercent = (time: number) => (time / duration) * 100;

  // Calculate segments between events
  const segments = useMemo(() => {
    if (events.length < 2) return [];
    const segs = [];
    for (let i = 0; i < events.length - 1; i++) {
      const start = events[i];
      const end = events[i+1];
      segs.push({ start, end });
    }
    return segs;
  }, [events]);

  return (
    <div className="relative w-full h-64 bg-gray-850 border border-gray-700 rounded-lg overflow-hidden select-none mb-4">
      {/* Time Grid Labels */}
      <div className="absolute inset-x-0 bottom-0 h-6 flex text-[10px] text-gray-500 font-mono px-2 pointer-events-none">
         <span className="flex-1">00:00</span>
         {[...Array(9)].map((_, i) => (
           <span key={i} className="flex-1 text-center border-l border-gray-700/50 pt-1">
             {new Date((duration * (i + 1) / 10) * 1000).toISOString().substr(14, 5)}
           </span>
         ))}
      </div>

      {/* Grid Lines */}
      <div className="absolute inset-0 flex pointer-events-none opacity-20">
        {[...Array(10)].map((_, i) => (
          <div key={i} className="flex-1 border-r border-gray-500 h-full"></div>
        ))}
      </div>

      {/* Playhead */}
      <div 
        className="absolute top-0 bottom-6 w-0.5 bg-red-500 z-30 transition-all duration-75 ease-linear pointer-events-none"
        style={{ left: `${widthPercent(playbackTime)}%` }}
      >
        <div className="w-2 h-2 bg-red-500 rounded-full -ml-[3px] -mt-1 shadow-glow" />
      </div>

      {/* Segments (Gradients) */}
      {segments.map((seg, idx) => (
        <div
          key={`seg-${seg.start.id}`}
          className="absolute top-12 bottom-12 bg-gradient-to-r from-accent-600/20 to-accent-600/20 border-t border-b border-accent-500/30"
          style={{
            left: `${widthPercent(seg.start.timeOffset)}%`,
            width: `${widthPercent(seg.end.timeOffset - seg.start.timeOffset)}%`
          }}
        >
          <div className="absolute inset-0 flex items-center justify-center text-[10px] text-accent-200/50 font-mono">
             {seg.end.timeOffset - seg.start.timeOffset}s
          </div>
        </div>
      ))}

      {/* Event Points & Labels */}
      {events.map((evt) => {
        const leftPos = widthPercent(evt.timeOffset);
        const isRightSided = leftPos > 85;

        return (
          <div
            key={evt.id}
            className="absolute top-0 bottom-6 w-0 group z-20"
            style={{ left: `${leftPos}%` }}
          >
            {/* Vertical Line */}
            <div className="absolute top-0 bottom-0 w-px bg-gray-500/50 group-hover:bg-white/80 transition-colors"></div>

            {/* Handle */}
            <div 
              className="absolute top-1/2 -mt-4 -ml-[6px] w-[12px] h-[32px] bg-gray-300 rounded-sm shadow-lg cursor-pointer hover:bg-white hover:scale-110 hover:z-50 transition-all flex items-center justify-center border border-gray-900"
              onClick={() => onEventClick(evt)}
            >
              <div className="w-0.5 h-4 bg-gray-500"></div>
            </div>

            {/* Always Visible Label */}
            <div 
              className={`absolute top-2 ${isRightSided ? 'right-2 items-end' : 'left-2 items-start'} flex flex-col pointer-events-none transition-opacity duration-200`}
            >
               <div className="bg-gray-900/80 backdrop-blur-sm border border-gray-700 px-2 py-1 rounded text-[10px] font-mono text-gray-300 whitespace-nowrap shadow-sm">
                  <span className="text-gray-500">@</span>{new Date(evt.timeOffset * 1000).toISOString().substr(14, 5)}
               </div>
               <div className="mt-1 bg-accent-900/80 backdrop-blur-sm border border-accent-700/50 px-2 py-1 rounded text-[10px] font-mono text-accent-100 whitespace-nowrap shadow-sm">
                  {evt.carrierFreq}<span className="text-accent-400">+</span>{evt.beatFreq}
               </div>
            </div>

            {/* Hover Actions */}
            <div className={`absolute bottom-2 ${isRightSided ? 'right-2' : 'left-2'} flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity bg-gray-900/90 p-1 rounded border border-gray-700`}>
               <button onClick={(e) => { e.stopPropagation(); onEventClick(evt); }} className="p-1 bg-blue-600 rounded hover:bg-blue-500 text-white">
                  <Edit size={10} />
               </button>
               <button onClick={(e) => { e.stopPropagation(); onDeleteEvent(evt.id); }} className="p-1 bg-red-600 rounded hover:bg-red-500 text-white">
                  <Trash2 size={10} />
               </button>
            </div>
          </div>
        );
      })}
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { 
  Play, Pause, Upload, Plus, FileCode, Activity, Music, 
  Volume2, Save, Wand2, RefreshCw, Trash
} from 'lucide-react';
import { BeatEvent, ViewMode } from './types';
import { parseScript, generateScript } from './services/parser';
import { audioEngine } from './services/audioEngine';
import { Timeline } from './components/Timeline';
import { Visualizer } from './components/Visualizer';
import { EventEditor } from './components/EventEditor';
import { GoogleGenAI } from "@google/genai";

const DEFAULT_SCRIPT = `# Example Binaural Session
# Time  Carrier+Beat/Volume
00:00 200+10/50
01:00 200+8/50
05:00 150+4/60
10:00 150+4/0
`;

function App() {
  const [script, setScript] = useState<string>(DEFAULT_SCRIPT);
  const [events, setEvents] = useState<BeatEvent[]>([]);
  const [isPlaying, setIsPlaying] = useState(false);
  const [viewMode, setViewMode] = useState<ViewMode>(ViewMode.TIMELINE);
  const [currentTime, setCurrentTime] = useState(0);
  const [editingEvent, setEditingEvent] = useState<BeatEvent | null>(null);
  const [aiPrompt, setAiPrompt] = useState("");
  const [isGenerating, setIsGenerating] = useState(false);

  // Ref for requestAnimationFrame to update UI during playback
  const rafRef = useRef<number>();

  // Parse script on load and when changed (debounce could be added)
  useEffect(() => {
    const newEvents = parseScript(script);
    setEvents(newEvents);
    audioEngine.loadEvents(newEvents);
  }, [script]);

  // Update script when events change via GUI
  const updateScriptFromEvents = (newEvents: BeatEvent[]) => {
    setEvents(newEvents);
    setScript(generateScript(newEvents));
    audioEngine.loadEvents(newEvents);
  };

  const handlePlayToggle = () => {
    if (isPlaying) {
      audioEngine.stop();
      setIsPlaying(false);
      cancelAnimationFrame(rafRef.current!);
    } else {
      audioEngine.play(currentTime);
      setIsPlaying(true);

      const updateLoop = () => {
        setCurrentTime(audioEngine.getCurrentTime());
        rafRef.current = requestAnimationFrame(updateLoop);
      };
      updateLoop();
    }
  };

  const handleSeek = (e: React.ChangeEvent<HTMLInputElement>) => {
    const time = parseFloat(e.target.value);
    setCurrentTime(time);
    if (isPlaying) {
       audioEngine.play(time); // Re-trigger play from new time
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (evt) => {
      const content = evt.target?.result as string;
      setScript(content);
    };
    reader.readAsText(file);
  };

  const handleDownload = () => {
    const blob = new Blob([script], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'binaural_session.sbg';
    a.click();
    URL.revokeObjectURL(url);
  };

  const handleNewSequence = () => {
    if (window.confirm("This will clear the current sequence. Continue?")) {
      const resetScript = `# New Session\n00:00 200+10/50\n`;
      setScript(resetScript);
      setCurrentTime(0);
      if (isPlaying) handlePlayToggle();
    }
  };

  const handleAddEvent = () => {
    const lastEvent = events[events.length - 1];
    const newTime = lastEvent ? lastEvent.timeOffset + 60 : 0;
    const newEvent: BeatEvent = {
      id: `evt_${Date.now()}`,
      timeOffset: newTime,
      carrierFreq: lastEvent?.carrierFreq || 200,
      beatFreq: lastEvent?.beatFreq || 10,
      volume: lastEvent?.volume || 50
    };
    updateScriptFromEvents([...events, newEvent]);
    setEditingEvent(newEvent);
  };

  const handleEventUpdate = (updated: BeatEvent) => {
    const newEvents = events.map(e => e.id === updated.id ? updated : e).sort((a,b) => a.timeOffset - b.timeOffset);
    updateScriptFromEvents(newEvents);
    setEditingEvent(null);
  };

  const handleDeleteEvent = (id: string) => {
    const newEvents = events.filter(e => e.id !== id);
    updateScriptFromEvents(newEvents);
  };

  const handleAiGenerate = async () => {
    if (!aiPrompt.trim()) return;
    setIsGenerating(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Convert this user description into a valid SBaGen script format (MM:SS Carrier+Beat/Volume). 
        The output must be ONLY the script text, starting with comments if needed but strictly following the format "MM:SS freq+beat/vol".
        Do not wrap in markdown blocks. 

        User Description: "${aiPrompt}"`,
        config: {
          systemInstruction: "You are an expert audio engineer specializing in SBaGen scripts.",
        }
      });

      const text = response.text;
      if (text) {
        // Simple cleanup to ensure no markdown backticks
        const cleanText = text.replace(/```/g, '').replace(/^sbg/, '').trim();
        setScript(cleanText);
        setAiPrompt("");
      }
    } catch (error) {
      console.error("AI Generation failed:", error);
      alert("Failed to generate script. Please check your API key or try again.");
    } finally {
      setIsGenerating(false);
    }
  };

  const totalDuration = events.length > 0 ? events[events.length - 1].timeOffset + 60 : 600;

  return (
    <div className="min-h-screen bg-gray-950 text-gray-200 font-sans flex flex-col">
      {/* Header */}
      <header className="bg-gray-900 border-b border-gray-800 p-4 flex items-center justify-between sticky top-0 z-40">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 bg-accent-600 rounded-lg flex items-center justify-center shadow-lg shadow-accent-900/50">
             <Activity className="text-white" />
          </div>
          <div>
            <h1 className="text-xl font-bold text-white tracking-tight">BinauralForge</h1>
            <p className="text-xs text-gray-500 font-mono">SBaGen Compatible Editor</p>
          </div>
        </div>

        <div className="flex items-center gap-4">
           {/* Toolbar */}
           <div className="flex bg-gray-800 rounded-lg p-1 border border-gray-700">
             <button 
                onClick={() => setViewMode(ViewMode.TIMELINE)}
                className={`p-2 rounded ${viewMode === ViewMode.TIMELINE ? 'bg-gray-700 text-white' : 'text-gray-400 hover:text-white'}`}
                title="Timeline View"
             >
                <Music size={18} />
             </button>
             <button 
                onClick={() => setViewMode(ViewMode.SCRIPT)}
                className={`p-2 rounded ${viewMode === ViewMode.SCRIPT ? 'bg-gray-700 text-white' : 'text-gray-400 hover:text-white'}`}
                title="Script View"
             >
                <FileCode size={18} />
             </button>
           </div>

           <div className="h-6 w-px bg-gray-800 mx-2" />

           <button 
              onClick={handleNewSequence}
              className="bg-gray-800 hover:bg-red-900/30 hover:text-red-400 text-gray-300 px-3 py-2 rounded border border-gray-700 transition-colors flex items-center gap-2 text-sm"
              title="Clear / New Sequence"
           >
             <RefreshCw size={16} />
             <span className="hidden sm:inline">New</span>
           </button>

           <label className="cursor-pointer bg-gray-800 hover:bg-gray-700 text-gray-300 px-3 py-2 rounded border border-gray-700 transition-colors flex items-center gap-2 text-sm">
             <Upload size={16} />
             <span className="hidden sm:inline">Load</span>
             <input type="file" className="hidden" accept=".sbg,.txt" onChange={handleFileUpload} />
           </label>

           <button 
              onClick={handleDownload}
              className="bg-gray-800 hover:bg-gray-700 text-gray-300 px-3 py-2 rounded border border-gray-700 transition-colors flex items-center gap-2 text-sm"
           >
             <Save size={16} />
             <span className="hidden sm:inline">Save</span>
           </button>
        </div>
      </header>

      {/* Main Content */}
      <main className="flex-1 flex flex-col p-6 gap-6 max-w-7xl mx-auto w-full">

        {/* Top Section: Visualization & Playback Controls */}
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
           <div className="lg:col-span-2 space-y-4">
              <Visualizer isPlaying={isPlaying} />

              {/* Transport Controls */}
              <div className="bg-gray-900 rounded-xl p-4 border border-gray-800 shadow-xl flex items-center gap-4">
                 <button 
