import { BeatEvent } from '../types';

export const parseScript = (script: string): BeatEvent[] => {
  const lines = script.split('\n');
  const events: BeatEvent[] = [];
  let idCounter = 0;

  // Map to store tone definitions: 'name' -> { carrier, beat, vol }
  const definitions: Record<string, { carrier: number, beat: number, vol: number }> = {};

  // Regex helpers
  // Matches definition: name: carrier+beat/vol
  // e.g., "alpha: 200+10/50"
  const defRegex = /^([a-zA-Z0-9_]+):\s+([\d.]+)\+([\d.]+)\/([\d.]+)/;

  // Matches time start: MM:SS or HH:MM:SS
  const timeStartRegex = /^(\d{1,2}):(\d{2})(?::(\d{2}))?/;

  // Matches explicit tone: carrier+beat/vol
  const toneRegex = /([\d.]+)\+([\d.]+)\/([\d.]+)/;

  lines.forEach((line) => {
    // Remove comments and whitespace
    const commentIndex = line.indexOf('#');
    const text = (commentIndex >= 0 ? line.substring(0, commentIndex) : line).trim();

    if (!text) return;

    // Check for definition assignment
    const defMatch = text.match(defRegex);
    if (defMatch) {
      definitions[defMatch[1]] = {
        carrier: parseFloat(defMatch[2]),
        beat: parseFloat(defMatch[3]),
        vol: parseFloat(defMatch[4])
      };
      return; 
    }

    // Check for Time Line
    const timeMatch = text.match(timeStartRegex);
    if (timeMatch) {
      let hours = 0, minutes = 0, seconds = 0;

      // Determine MM:SS or HH:MM:SS
      if (timeMatch[3]) {
        hours = parseInt(timeMatch[1], 10);
        minutes = parseInt(timeMatch[2], 10);
        seconds = parseInt(timeMatch[3], 10);
      } else {
        minutes = parseInt(timeMatch[1], 10);
        seconds = parseInt(timeMatch[2], 10);
      }
      const totalSeconds = hours * 3600 + minutes * 60 + seconds;

      // Extract the part after the time string
      const remainder = text.substring(timeMatch[0].length).trim();

      let carrier = 0, beat = 0, vol = 0;
      let found = false;

      // Split remainder into words to check for variable names
      const words = remainder.split(/\s+/);
      const firstWord = words[0];

      // Case 1: Reference to a definition (e.g., "00:00 alpha")
      if (firstWord && definitions[firstWord]) {
          const def = definitions[firstWord];
          carrier = def.carrier;
          beat = def.beat;
          vol = def.vol;
          found = true;
      } 
      // Case 2: Explicit definition (e.g., "00:00 200+10/50")
      else {
          const toneMatch = remainder.match(toneRegex);
          if (toneMatch) {
              carrier = parseFloat(toneMatch[1]);
              beat = parseFloat(toneMatch[2]);
              vol = parseFloat(toneMatch[3]);
              found = true;
          }
      }

      if (found) {
        events.push({
            id: `evt_${idCounter++}_${Date.now()}`,
            timeOffset: totalSeconds,
            carrierFreq: carrier,
            beatFreq: beat,
            volume: vol,
        });
      } else if (firstWord === 'off' || firstWord === '.') {
         // Handle 'off' or '.' as silence
         events.push({
            id: `evt_${idCounter++}_${Date.now()}`,
            timeOffset: totalSeconds,
            carrierFreq: 0,
            beatFreq: 0,
            volume: 0,
        });
      }
    }
  });

  return events.sort((a, b) => a.timeOffset - b.timeOffset);
};

export const generateScript = (events: BeatEvent[]): string => {
  let script = "# Generated by BinauralForge\n# Time Carrier+Beat/Volume\n\n";

  events.forEach(evt => {
    const h = Math.floor(evt.timeOffset / 3600);
    const m = Math.floor((evt.timeOffset % 3600) / 60);
    const s = Math.floor(evt.timeOffset % 60);

    // Format: HH:MM:SS or MM:SS
    let timeStr = "";
    if (h > 0) {
        timeStr = `${h.toString().padStart(2, '0')}:${m.toString().padStart(2, '0')}:${s.toString().padStart(2, '0')}`;
    } else {
        timeStr = `${m.toString().padStart(2, '0')}:${s.toString().padStart(2, '0')}`;
    }

    script += `${timeStr} ${evt.carrierFreq.toFixed(1)}+${evt.beatFreq.toFixed(2)}/${evt.volume.toFixed(1)}\n`;
  });

  return script;
};

import React, { useState, useEffect, useRef } from 'react';
import { 
  Play, Pause, Upload, Plus, FileCode, Activity, Music, 
  Volume2, Save, Wand2, RefreshCw
} from 'lucide-react';
import { BeatEvent, ViewMode } from './types';
import { parseScript, generateScript } from './services/parser';
import { audioEngine } from './services/audioEngine';
import { Timeline } from './components/Timeline';
import { Visualizer } from './components/Visualizer';
import { EventEditor } from './components/EventEditor';
import { GoogleGenAI } from "@google/genai";

const DEFAULT_SCRIPT = `# Example Binaural Session
# Time  Carrier+Beat/Volume
00:00 200+10/50
01:00 200+8/50
05:00 150+4/60
10:00 150+4/0
`;

function App() {
  const [script, setScript] = useState<string>(DEFAULT_SCRIPT);
  const [events, setEvents] = useState<BeatEvent[]>([]);
  const [isPlaying, setIsPlaying] = useState(false);
  const [viewMode, setViewMode] = useState<ViewMode>(ViewMode.TIMELINE);
  const [currentTime, setCurrentTime] = useState(0);
  const [editingEvent, setEditingEvent] = useState<BeatEvent | null>(null);
  const [aiPrompt, setAiPrompt] = useState("");
  const [isGenerating, setIsGenerating] = useState(false);

  const rafRef = useRef<number>();

  // Parse script on load and when changed
  useEffect(() => {
    const newEvents = parseScript(script);
    setEvents(newEvents);
    audioEngine.loadEvents(newEvents);
  }, [script]);

  // Update script when events change via GUI
  const updateScriptFromEvents = (newEvents: BeatEvent[]) => {
    setEvents(newEvents);
    setScript(generateScript(newEvents));
    audioEngine.loadEvents(newEvents);
  };

  const handlePlayToggle = () => {
    if (isPlaying) {
      audioEngine.stop();
      setIsPlaying(false);
      cancelAnimationFrame(rafRef.current!);
    } else {
      audioEngine.play(currentTime);
      setIsPlaying(true);

      const updateLoop = () => {
        setCurrentTime(audioEngine.getCurrentTime());
        rafRef.current = requestAnimationFrame(updateLoop);
      };
      updateLoop();
    }
  };

  const handleSeek = (e: React.ChangeEvent<HTMLInputElement>) => {
    const time = parseFloat(e.target.value);
    setCurrentTime(time);
    if (isPlaying) {
       audioEngine.play(time);
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (evt) => {
      const content = evt.target?.result as string;
      setScript(content);
    };
    reader.readAsText(file);
    e.target.value = ''; // Reset input to allow reloading same file
  };

  const handleDownload = () => {
    const blob = new Blob([script], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'binaural_session.sbg';
    a.click();
    URL.revokeObjectURL(url);
  };

  const handleNewSequence = () => {
    if (window.confirm("This will clear the current sequence. Continue?")) {
      const resetScript = `# New Session\n00:00 200+10/50\n`;
      setScript(resetScript);
      setCurrentTime(0);
      if (isPlaying) handlePlayToggle();
    }
  };

  const handleAddEvent = () => {
    const lastEvent = events[events.length - 1];
    const newTime = lastEvent ? lastEvent.timeOffset + 60 : 0;
    const newEvent: BeatEvent = {
      id: `evt_${Date.now()}`,
      timeOffset: newTime,
      carrierFreq: lastEvent?.carrierFreq || 200,
      beatFreq: lastEvent?.beatFreq || 10,
      volume: lastEvent?.volume || 50
    };
    updateScriptFromEvents([...events, newEvent]);
    setEditingEvent(newEvent);
  };

  const handleEventUpdate = (updated: BeatEvent) => {
    const newEvents = events.map(e => e.id === updated.id ? updated : e).sort((a,b) => a.timeOffset - b.timeOffset);
    updateScriptFromEvents(newEvents);
    setEditingEvent(null);
  };

  const handleDeleteEvent = (id: string) => {
    const newEvents = events.filter(e => e.id !== id);
    updateScriptFromEvents(newEvents);
  };

  const handleAiGenerate = async () => {
    if (!aiPrompt.trim()) return;
    setIsGenerating(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Convert this user description into a valid SBaGen script format (MM:SS Carrier+Beat/Volume). 
        The output must be ONLY the script text, starting with comments if needed but strictly following the format "MM:SS freq+beat/vol".
        Do not wrap in markdown blocks. 

        User Description: "${aiPrompt}"`,
        config: {
          systemInstruction: "You are an expert audio engineer specializing in SBaGen scripts.",
        }
      });

      const text = response.text;
      if (text) {
        // Simple cleanup
        const cleanText = text.replace(/```/g, '').replace(/^sbg/, '').trim();
        setScript(cleanText);
        setAiPrompt("");
      }
    } catch (error) {
      console.error("AI Generation failed:", error);
      alert("Failed to generate script. Please check your API key or try again.");
    } finally {
      setIsGenerating(false);
    }
  };

  const totalDuration = events.length > 0 ? events[events.length - 1].timeOffset + 60 : 600;

  return (
    <div className="min-h-screen bg-gray-950 text-gray-200 font-sans flex flex-col">
      {/* Header */}
      <header className="bg-gray-900 border-b border-gray-800 p-4 flex items-center justify-between sticky top-0 z-40">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 bg-accent-600 rounded-lg flex items-center justify-center shadow-lg shadow-accent-900/50">
             <Activity className="text-white" />
          </div>
          <div>
            <h1 className="text-xl font-bold text-white tracking-tight">BinauralForge</h1>
            <p className="text-xs text-gray-500 font-mono">SBaGen Compatible Editor</p>
          </div>
        </div>

        <div className="flex items-center gap-4">
           {/* Toolbar */}
           <div className="flex bg-gray-800 rounded-lg p-1 border border-gray-700">
             <button 
                onClick={() => setViewMode(ViewMode.TIMELINE)}
                className={`p-2 rounded ${viewMode === ViewMode.TIMELINE ? 'bg-gray-700 text-white' : 'text-gray-400 hover:text-white'}`}
                title="Timeline View"
             >
                <Music size={18} />
             </button>
             <button 
                onClick={() => setViewMode(ViewMode.SCRIPT)}
                className={`p-2 rounded ${viewMode === ViewMode.SCRIPT ? 'bg-gray-700 text-white' : 'text-gray-400 hover:text-white'}`}
                title="Script View"
             >
                <FileCode size={18} />
             </button>
           </div>

           <div className="h-6 w-px bg-gray-800 mx-2" />

           <button 
              onClick={handleNewSequence}
              className="bg-gray-800 hover:bg-red-900/30 hover:text-red-400 text-gray-300 px-3 py-2 rounded border border-gray-700 transition-colors flex items-center gap-2 text-sm"
              title="Clear / New Sequence"
           >
             <RefreshCw size={16} />
             <span className="hidden sm:inline">New</span>
           </button>

           <label className="cursor-pointer bg-gray-800 hover:bg-gray-700 text-gray-300 px-3 py-2 rounded border border-gray-700 transition-colors flex items-center gap-2 text-sm">
             <Upload size={16} />
             <span className="hidden sm:inline">Load</span>
             <input type="file" className="hidden" accept=".sbg,.txt" onChange={handleFileUpload} />
           </label>

           <button 
              onClick={handleDownload}
              className="bg-gray-800 hover:bg-gray-700 text-gray-300 px-3 py-2 rounded border border-gray-700 transition-colors flex items-center gap-2 text-sm"
           >
             <Save size={16} />
             <span className="hidden sm:inline">Save</span>
           </button>
        </div>
      </header>

      {/* Main Content */}
      <main className="flex-1 flex flex-col p-6 gap-6 max-w-7xl mx-auto w-full">

        {/* Top Section: Visualization & Playback Controls */}
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
           <div className="lg:col-span-2 space-y-4">
              <Visualizer isPlaying={isPlaying} />

              {/* Transport Controls */}
              <div className="bg-gray-900 rounded-xl p-4 border border-gray-800 shadow-xl flex items-center gap-4">
                 <button 
                    onClick={handlePlayToggle}
                    className={`w-12 h-12 rounded-full flex items-center justify-center transition-all ${isPlaying ? 'bg-red-500 hover:bg-red-600' : 'bg-green-500 hover:bg-green-600'} text-white shadow-lg`}
                 >
                    {isPlaying ? <Pause size={20} fill="currentColor" /> : <Play size={20} fill="currentColor" className="ml-1" />}
                 </button>

                 <div className="flex-1">
                    <div className="flex justify-between text-xs font-mono text-gray-500 mb-1">
                       <span>{new Date(currentTime * 1000).toISOString().substr(14, 5)}</span>
                       <span>{new Date(totalDuration * 1000).toISOString().substr(14, 5)}</span>
                    </div>
                    <input 
                      type="range" 
                      min="0" 
                      max={totalDuration} 
                      value={currentTime} 
                      onChange={handleSeek}
                      className="w-full h-2 bg-gray-800 rounded-lg appearance-none cursor-pointer accent-accent-500"
                    />
                 </div>

                 <div className="flex items-center gap-2 text-gray-400">
                    <Volume2 size={16} />
                    <div className="w-20 h-1 bg-gray-800 rounded-full overflow-hidden">
                       <div className="w-1/2 h-full bg-gray-500"></div>
                    </div>
                 </div>
              </div>
           </div>

           {/* Stats / Info Panel */}
           <div className="bg-gray-900 rounded-xl p-6 border border-gray-800 flex flex-col justify-center">
              <h3 className="text-gray-500 uppercase tracking-wider text-xs font-semibold mb-4">Current Parameters</h3>
              <div className="grid grid-cols-2 gap-y-6">
                 <div>
                    <div className="text-2xl font-mono text-white">
                      {isPlaying ? audioEngine.analyserLeft ? events.find(e => e.timeOffset <= currentTime && currentTime < (events.find(n => n.timeOffset > currentTime)?.timeOffset || Infinity))?.carrierFreq || '-' : '-' : '-'}
                      <span className="text-sm text-gray-600 ml-1">Hz</span>
                    </div>
                    <div className="text-xs text-gray-500">Carrier</div>
                 </div>
                 <div>
                    <div className="text-2xl font-mono text-accent-400">
                    {isPlaying ? audioEngine.analyserLeft ? events.find(e => e.timeOffset <= currentTime && currentTime < (events.find(n => n.timeOffset > currentTime)?.timeOffset || Infinity))?.beatFreq || '-' : '-' : '-'}
                    <span className="text-sm text-gray-600 ml-1">Hz</span>
                    </div>
                    <div className="text-xs text-gray-500">Binaural Beat</div>
                 </div>
                 <div>
                    <div className="text-xl font-mono text-gray-300">Sine</div>
                    <div className="text-xs text-gray-500">Waveform</div>
                 </div>
                 <div>
                    <div className="text-xl font-mono text-gray-300">Pink</div>
                    <div className="text-xs text-gray-500">Noise (Mock)</div>
