           </div>
        </div>

        {/* Editor Area - Split Layout */}
        <div className="flex-1 min-h-[500px] bg-gray-900 rounded-xl border border-gray-800 overflow-hidden relative">
           {viewMode === ViewMode.TIMELINE ? (
             <div className="flex h-full flex-col md:flex-row">
                {/* Left: Timeline (50%) */}
                <div className="w-full md:w-1/2 p-6 h-full flex flex-col border-b md:border-b-0 md:border-r border-gray-800">
                    <div className="flex justify-between items-start mb-6">
                       <div>
                           <h2 className="text-lg font-semibold text-white">Sequence Timeline</h2>
                           {/* Real-time Frequency Display Above Timeline */}
                           <div className="mt-4 p-3 bg-gray-850 rounded-lg border border-gray-700/50 inline-block shadow-inner">
                               <div className="text-xs text-gray-500 uppercase tracking-widest mb-1">Current Beat</div>
                               <div className="text-4xl font-mono font-bold text-accent-400 tabular-nums leading-none">
                                  {liveBeat.toFixed(2)}<span className="text-lg text-gray-600 ml-1 font-sans font-normal">Hz</span>
                               </div>
                           </div>
                       </div>
                       <button 
                          onClick={handleAddEvent}
                          className="bg-gray-800 hover:bg-gray-700 text-white px-3 py-1.5 rounded text-sm flex items-center gap-1 transition-colors border border-gray-700"
                       >
                          <Plus size={16} /> Add Event
                       </button>
                    </div>

                    <div className="flex-1 overflow-y-auto min-h-[250px] relative">
                       <Timeline 
                          events={events} 
                          duration={totalDuration} 
                          onEventClick={setEditingEvent} 
                          onDeleteEvent={handleDeleteEvent}
