                  value={script}
                  onChange={(e) => setScript(e.target.value)}
                  className="flex-1 bg-gray-950 text-gray-300 font-mono p-4 outline-none resize-none text-sm leading-relaxed"
                  spellCheck={false}
                />
             </div>
           )}
        </div>
      </main>

      {/* Modals */}
      <EventEditor 
         event={editingEvent} 
         onSave={handleEventUpdate} 
         onCancel={() => setEditingEvent(null)} 
