import { BeatEvent } from '../types';

class BinauralAudioEngine {
  private ctx: AudioContext | null = null;
  private masterGain: GainNode | null = null;

  // Left Channel
  private oscLeft: OscillatorNode | null = null;
  private pannerLeft: StereoPannerNode | null = null;

  // Right Channel
  private oscRight: OscillatorNode | null = null;
  private pannerRight: StereoPannerNode | null = null;

  // Analysis
  public analyserLeft: AnalyserNode | null = null;
  public analyserRight: AnalyserNode | null = null;

  private isRunning: boolean = false;
  private events: BeatEvent[] = [];
  private playbackStartTime: number = 0;
  private pausedAt: number = 0;
  private masterVolume: number = 0.5;

  constructor() {}

  init() {
    if (this.ctx) return;
    this.ctx = new (window.AudioContext || (window as any).webkitAudioContext)();
    this.masterGain = this.ctx.createGain();
    this.masterGain.connect(this.ctx.destination);
    this.masterGain.gain.value = this.masterVolume;

    this.analyserLeft = this.ctx.createAnalyser();
    this.analyserRight = this.ctx.createAnalyser();
    this.analyserLeft.fftSize = 512;
    this.analyserRight.fftSize = 512;
  }

  setMasterVolume(percent: number) {
    this.masterVolume = Math.max(0, Math.min(1, percent / 100));
    if (this.masterGain && this.ctx) {
      this.masterGain.gain.setTargetAtTime(this.masterVolume, this.ctx.currentTime, 0.05);
    }
  }

  private clearOscillators() {
    [this.oscLeft, this.oscRight].forEach(osc => {
      if (osc) {
        try { osc.stop(); } catch(e) {}
        osc.disconnect();
      }
    });
    this.oscLeft = null;
    this.oscRight = null;
  }

  private createOscillators(startTime: number) {
    if (!this.ctx || !this.masterGain) return;
    this.clearOscillators();

    this.oscLeft = this.ctx.createOscillator();
    this.pannerLeft = this.ctx.createStereoPanner();
    this.pannerLeft.pan.value = -1;

    this.oscRight = this.ctx.createOscillator();
    this.pannerRight = this.ctx.createStereoPanner();
    this.pannerRight.pan.value = 1;

    this.oscLeft.connect(this.pannerLeft);
    if(this.analyserLeft) this.pannerLeft.connect(this.analyserLeft);
    this.pannerLeft.connect(this.masterGain);

    this.oscRight.connect(this.pannerRight);
    if(this.analyserRight) this.pannerRight.connect(this.analyserRight);
    this.pannerRight.connect(this.masterGain);

    const now = this.ctx.currentTime;

    // Improved Scheduling Logic: Ramping between events
    this.events.forEach((evt, index) => {
      const evtTime = now + (evt.timeOffset - startTime);
      const nextEvt = this.events[index + 1];

      const leftFreq = evt.carrierFreq - (evt.beatFreq / 2);
      const rightFreq = evt.carrierFreq + (evt.beatFreq / 2);

      if (evtTime <= now) {
        // If we are currently past or at this event, set immediate values
        this.oscLeft?.frequency.setValueAtTime(leftFreq, now);
        this.oscRight?.frequency.setValueAtTime(rightFreq, now);
      } else {
        // Linear ramp to next state for a smoother professional feel
        this.oscLeft?.frequency.linearRampToValueAtTime(leftFreq, evtTime);
        this.oscRight?.frequency.linearRampToValueAtTime(rightFreq, evtTime);
      }
    });

    this.oscLeft.start(now);
    this.oscRight.start(now);
  }

  loadEvents(events: BeatEvent[]) {
    this.events = [...events].sort((a, b) => a.timeOffset - b.timeOffset);
    if (this.isRunning) {
      // Re-schedule if running to reflect changes immediately
      this.createOscillators(this.getCurrentTime());
    }
  }

  play(offset: number = 0) {
    if (!this.ctx) this.init();
    if (this.ctx?.state === 'suspended') this.ctx.resume();

    this.pausedAt = offset;
    this.createOscillators(offset);
    this.isRunning = true;
    this.playbackStartTime = this.ctx!.currentTime - offset;
  }

  stop() {
    this.clearOscillators();
    this.isRunning = false;
  }

  getCurrentTime(): number {
    if (!this.isRunning || !this.ctx) return this.pausedAt;
    return this.ctx.currentTime - this.playbackStartTime;
  }

  getIsRunning(): boolean {
    return this.isRunning;
  }
}

export const audioEngine = new BinauralAudioEngine();

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { 
  Play, Pause, Upload, Plus, FileCode, Activity, Music, 
  Volume2, Save, Wand2, RefreshCw
} from 'lucide-react';
import { BeatEvent, ViewMode } from './types';
import { parseScript, generateScript } from './services/parser';
import { audioEngine } from './services/audioEngine';
import { Timeline } from './components/Timeline';
import { Visualizer } from './components/Visualizer';
import { EventEditor } from './components/EventEditor';
import { GoogleGenAI } from "@google/genai";

const DEFAULT_SCRIPT = `# Example Binaural Session
# Time  Carrier+Beat/Volume
00:00 200+10/50
01:00 200+8/50
05:00 150+4/60
10:00 150+4/0
`;

function App() {
  const [script, setScript] = useState<string>(DEFAULT_SCRIPT);
  const [events, setEvents] = useState<BeatEvent[]>([]);
  const [isPlaying, setIsPlaying] = useState(false);
  const [viewMode, setViewMode] = useState<ViewMode>(ViewMode.TIMELINE);
  const [currentTime, setCurrentTime] = useState(0);
  const [editingEvent, setEditingEvent] = useState<BeatEvent | null>(null);
  const [aiPrompt, setAiPrompt] = useState("");
  const [isGenerating, setIsGenerating] = useState(false);
  const [volume, setVolume] = useState(50);

  const rafRef = useRef<number>(0);

  // Synchronize script and events
  useEffect(() => {
    const newEvents = parseScript(script);
    setEvents(newEvents);
    audioEngine.loadEvents(newEvents);
  }, [script]);

  const updateScriptFromEvents = useCallback((newEvents: BeatEvent[]) => {
    const sorted = [...newEvents].sort((a,b) => a.timeOffset - b.timeOffset);
    setEvents(sorted);
    setScript(generateScript(sorted));
    audioEngine.loadEvents(sorted);
  }, []);

  const handlePlayToggle = () => {
    if (isPlaying) {
      audioEngine.stop();
      setIsPlaying(false);
      cancelAnimationFrame(rafRef.current);
    } else {
      audioEngine.play(currentTime);
      setIsPlaying(true);

      const updateLoop = () => {
        const time = audioEngine.getCurrentTime();
        setCurrentTime(time);
        rafRef.current = requestAnimationFrame(updateLoop);
      };
      updateLoop();
    }
  };

  const handleSeek = (e: React.ChangeEvent<HTMLInputElement>) => {
    const time = parseFloat(e.target.value);
    setCurrentTime(time);
    if (isPlaying) {
       audioEngine.play(time);
    }
  };

  const handleVolumeChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const val = parseFloat(e.target.value);
    setVolume(val);
    audioEngine.setMasterVolume(val);
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (evt) => setScript(evt.target?.result as string);
    reader.readAsText(file);
    e.target.value = '';
  };

  const handleDownload = () => {
    const blob = new Blob([script], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'binaural_session.sbg';
    a.click();
    URL.revokeObjectURL(url);
  };

  const handleNewSequence = () => {
    if (window.confirm("Start a new session? Current progress will be lost.")) {
      setScript(`# New Session\n00:00 200+10/50\n`);
      setCurrentTime(0);
      if (isPlaying) handlePlayToggle();
    }
  };

  const handleAddEvent = () => {
    const lastEvent = events[events.length - 1];
    const newTime = lastEvent ? lastEvent.timeOffset + 60 : 0;
    const newEvent: BeatEvent = {
      id: `evt_${Date.now()}`,
      timeOffset: newTime,
      carrierFreq: lastEvent?.carrierFreq || 200,
      beatFreq: lastEvent?.beatFreq || 10,
      volume: lastEvent?.volume || 50
    };
    updateScriptFromEvents([...events, newEvent]);
    setEditingEvent(newEvent);
  };

  const handleEventUpdate = (updated: BeatEvent) => {
    updateScriptFromEvents(events.map(e => e.id === updated.id ? updated : e));
    setEditingEvent(null);
  };

  const handleDeleteEvent = (id: string) => {
    updateScriptFromEvents(events.filter(e => e.id !== id));
  };

  const handleAiGenerate = async () => {
    if (!aiPrompt.trim()) return;
    setIsGenerating(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Create an SBaGen script for: "${aiPrompt}". Format: MM:SS Freq+Beat/Vol. Strictly text only.`,
        config: { systemInstruction: "Expert SBaGen Engineer." }
      });
      if (response.text) {
        setScript(response.text.replace(/```/g, '').trim());
        setAiPrompt("");
      }
    } catch (e) {
      console.error(e);
    } finally {
      setIsGenerating(false);
    }
  };

  const getCurrentValues = () => {
    if (events.length === 0) return { carrier: 0, beat: 0 };
    let startEvt = events[0];
    let endEvt = null;
    for (let i = 0; i < events.length; i++) {
        if (currentTime >= events[i].timeOffset) {
            startEvt = events[i];
            endEvt = events[i+1] || null;
        }
    }
    if (!endEvt) return { carrier: startEvt.carrierFreq, beat: startEvt.beatFreq };
    const progress = (currentTime - startEvt.timeOffset) / (endEvt.timeOffset - startEvt.timeOffset);
    return {
      carrier: startEvt.carrierFreq + (endEvt.carrierFreq - startEvt.carrierFreq) * progress,
      beat: startEvt.beatFreq + (endEvt.beatFreq - startEvt.beatFreq) * progress
    };
  };

  const { carrier: liveCarrier, beat: liveBeat } = getCurrentValues();
  const totalDuration = events.length > 0 ? events[events.length - 1].timeOffset + 60 : 600;

  return (
    <div className="min-h-screen bg-gray-950 text-gray-200 font-sans flex flex-col selection:bg-accent-500/30">
      <header className="bg-gray-900 border-b border-gray-800 p-4 flex items-center justify-between sticky top-0 z-40 backdrop-blur-md bg-opacity-80">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 bg-accent-600 rounded-lg flex items-center justify-center shadow-lg shadow-accent-900/50 transition-transform hover:scale-105">
             <Activity className="text-white" />
          </div>
          <div>
            <h1 className="text-xl font-bold text-white tracking-tight">BinauralForge</h1>
            <p className="text-[10px] text-gray-500 font-mono uppercase tracking-widest">v2.0 Refactor</p>
          </div>
        </div>

        <div className="flex items-center gap-3">
           <div className="flex bg-gray-800 rounded-lg p-1 border border-gray-700">
             <button onClick={() => setViewMode(ViewMode.TIMELINE)} className={`p-2 rounded transition-all ${viewMode === ViewMode.TIMELINE ? 'bg-gray-700 text-white shadow-inner' : 'text-gray-400 hover:text-white'}`}><Music size={18} /></button>
             <button onClick={() => setViewMode(ViewMode.SCRIPT)} className={`p-2 rounded transition-all ${viewMode === ViewMode.SCRIPT ? 'bg-gray-700 text-white shadow-inner' : 'text-gray-400 hover:text-white'}`}><FileCode size={18} /></button>
           </div>
           <div className="h-6 w-px bg-gray-800 mx-1" />
           <button onClick={handleNewSequence} className="bg-gray-800 hover:bg-red-900/20 hover:text-red-400 text-gray-300 px-3 py-2 rounded border border-gray-700 transition-all text-sm flex items-center gap-2"><RefreshCw size={14} /><span className="hidden sm:inline">New</span></button>
           <label className="cursor-pointer bg-gray-800 hover:bg-gray-700 text-gray-300 px-3 py-2 rounded border border-gray-700 transition-all text-sm flex items-center gap-2"><Upload size={14} /><span className="hidden sm:inline">Load</span><input type="file" className="hidden" accept=".sbg,.txt" onChange={handleFileUpload} /></label>
           <button onClick={handleDownload} className="bg-accent-600 hover:bg-accent-500 text-white px-3 py-2 rounded border border-accent-500 transition-all text-sm flex items-center gap-2"><Save size={14} /><span className="hidden sm:inline">Export</span></button>
        </div>
      </header>

      <main className="flex-1 flex flex-col p-6 gap-6 max-w-7xl mx-auto w-full">
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
           <div className="lg:col-span-2 space-y-4">
              <Visualizer isPlaying={isPlaying} />
              <div className="bg-gray-900 rounded-xl p-4 border border-gray-800 shadow-2xl flex items-center gap-4">
                 <button onClick={handlePlayToggle} className={`w-14 h-14 rounded-full flex items-center justify-center transition-all transform hover:scale-105 active:scale-95 ${isPlaying ? 'bg-red-500 hover:bg-red-600 shadow-lg shadow-red-900/40' : 'bg-green-500 hover:bg-green-600 shadow-lg shadow-green-900/40'} text-white`}>
                    {isPlaying ? <Pause size={24} fill="currentColor" /> : <Play size={24} fill="currentColor" className="ml-1" />}
                 </button>
                 <div className="flex-1 px-2">
                    <div className="flex justify-between text-[10px] font-mono text-gray-500 mb-2 uppercase tracking-tighter">
