                       <span>{new Date(totalDuration * 1000).toISOString().substr(14, 5)}</span>
                    </div>
                    <input type="range" min="0" max={totalDuration} value={currentTime} onChange={handleSeek} className="w-full h-1.5 bg-gray-800 rounded-lg appearance-none cursor-pointer accent-accent-500" />
                 </div>
                 <div className="flex items-center gap-3 text-gray-400 w-32 bg-gray-800/50 p-2 rounded-lg border border-gray-700">
                    <Volume2 size={16} />
                    <input type="range" min="0" max="100" value={volume} onChange={handleVolumeChange} className="w-full h-1 bg-gray-700 rounded-lg appearance-none cursor-pointer accent-gray-400" />
                 </div>
              </div>
           </div>

           <div className="bg-gray-900 rounded-xl p-6 border border-gray-800 shadow-xl flex flex-col justify-between relative overflow-hidden group">
              <div className="absolute top-0 right-0 p-4 opacity-10 group-hover:opacity-20 transition-opacity"><Activity size={80} /></div>
              <h3 className="text-gray-500 uppercase tracking-widest text-[10px] font-bold mb-4">DSP Real-time Metrics</h3>
              <div className="space-y-6 relative z-10">
                 <div className="flex justify-between items-end border-b border-gray-800 pb-2">
                    <div><div className="text-xs text-gray-500 uppercase">Carrier</div><div className="text-3xl font-mono text-white leading-none">{liveCarrier.toFixed(1)}<span className="text-xs text-gray-600 ml-1">Hz</span></div></div>
                    <div className="text-right"><div className="text-xs text-gray-500 uppercase">Beat</div><div className="text-3xl font-mono text-accent-400 leading-none">{liveBeat.toFixed(2)}<span className="text-xs text-gray-600 ml-1">Hz</span></div></div>
                 </div>
                 <div className="grid grid-cols-2 gap-4">
                    <div><div className="text-[10px] text-gray-500 uppercase">Oscillator</div><div className="text-sm font-mono text-gray-300">Pure Sine</div></div>
                    <div><div className="text-[10px] text-gray-500 uppercase">State</div><div className={`text-sm font-mono ${isPlaying ? 'text-green-400' : 'text-orange-400'}`}>{isPlaying ? 'Active' : 'Standby'}</div></div>
                 </div>
              </div>
           </div>
        </div>

        <div className="bg-gradient-to-r from-gray-900 to-gray-850 rounded-xl p-1 border border-gray-700/50 shadow-inner group">
           <div className="flex flex-col sm:flex-row gap-2 p-2">
              <div className="flex-1 relative">
                 <input type="text" placeholder="Generate session via AI (e.g. 'deep sleep starting at 8Hz ramping to 1Hz over 30 mins')" className="w-full bg-gray-950 border border-gray-700 rounded-lg px-4 py-3 text-gray-200 focus:ring-2 focus:ring-accent-500 outline-none text-sm placeholder-gray-600 font-mono transition-all" value={aiPrompt} onChange={(e) => setAiPrompt(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && handleAiGenerate()} />
                 <Wand2 className="absolute right-4 top-1/2 -translate-y-1/2 text-gray-700 group-hover:text-accent-500 transition-colors" size={18} />
