import { BeatEvent } from '../types';

class BinauralAudioEngine {
  private ctx: AudioContext | null = null;
  private masterGain: GainNode | null = null;

  // Binaural Oscillators
  private oscLeft: OscillatorNode | null = null;
  private oscRight: OscillatorNode | null = null;
  private pannerLeft: StereoPannerNode | null = null;
  private pannerRight: StereoPannerNode | null = null;

  // Noise Generator (Pink Noise)
  private noiseNode: AudioWorkletNode | ScriptProcessorNode | null = null;
  private noiseGain: GainNode | null = null;

  // LFO for organic drifting
  private lfo: OscillatorNode | null = null;
  private lfoGain: GainNode | null = null;

  // Analysis
  public analyserLeft: AnalyserNode | null = null;
  public analyserRight: AnalyserNode | null = null;

  private isRunning: boolean = false;
  private events: BeatEvent[] = [];
  private playbackStartTime: number = 0;
  private pausedAt: number = 0;
  private masterVolume: number = 0.5;
  private noiseLevel: number = 0.15; // Default ambient noise floor

  constructor() {}

  init() {
    if (this.ctx) return;
    this.ctx = new (window.AudioContext || (window as any).webkitAudioContext)();
    this.masterGain = this.ctx.createGain();
    this.masterGain.connect(this.ctx.destination);
    this.masterGain.gain.value = this.masterVolume;

    this.analyserLeft = this.ctx.createAnalyser();
    this.analyserRight = this.ctx.createAnalyser();
    this.analyserLeft.fftSize = 512;
    this.analyserRight.fftSize = 512;

    this.setupNoise();
    this.setupLFO();
  }

  private setupLFO() {
    if (!this.ctx || !this.masterGain) return;
    // Slow drifting LFO to make the sound less static
    this.lfo = this.ctx.createOscillator();
    this.lfoGain = this.ctx.createGain();
    this.lfo.frequency.value = 0.1; // 0.1Hz very slow drift
    this.lfoGain.gain.value = 0.05; // 5% modulation
    this.lfo.connect(this.lfoGain);
    // We don't connect it directly to volume to avoid "pumping", 
    // instead it could be used to modulate frequency if desired.
    this.lfo.start();
  }

  private setupNoise() {
    if (!this.ctx || !this.masterGain) return;

    // Pink noise implementation using ScriptProcessor (fallback for wide compatibility)
    const bufferSize = 4096;
    let b0, b1, b2, b3, b4, b5, b6;
    b0 = b1 = b2 = b3 = b4 = b5 = b6 = 0.0;

    const node = this.ctx.createScriptProcessor(bufferSize, 1, 1);
    node.onaudioprocess = (e) => {
      const output = e.outputBuffer.getChannelData(0);
      for (let i = 0; i < bufferSize; i++) {
        const white = Math.random() * 2 - 1;
        b0 = 0.99886 * b0 + white * 0.0555179;
        b1 = 0.99332 * b1 + white * 0.0750759;
        b2 = 0.96900 * b2 + white * 0.1538520;
        b3 = 0.86650 * b3 + white * 0.3104856;
        b4 = 0.55000 * b4 + white * 0.5329522;
        b5 = -0.7616 * b5 - white * 0.0168980;
        output[i] = b0 + b1 + b2 + b3 + b4 + b5 + b6 + white * 0.5362;
        output[i] *= 0.11; // estimate
        b6 = white * 0.115926;
      }
    };

    this.noiseGain = this.ctx.createGain();
    this.noiseGain.gain.value = this.noiseLevel;
    node.connect(this.noiseGain);
    this.noiseGain.connect(this.masterGain);
    this.noiseNode = node;
  }

  setMasterVolume(percent: number) {
    this.masterVolume = Math.max(0, Math.min(1, percent / 100));
    if (this.masterGain && this.ctx) {
      this.masterGain.gain.setTargetAtTime(this.masterVolume, this.ctx.currentTime, 0.05);
    }
  }

  setNoiseLevel(percent: number) {
    this.noiseLevel = Math.max(0, Math.min(1, percent / 100));
    if (this.noiseGain && this.ctx) {
      this.noiseGain.gain.setTargetAtTime(this.noiseLevel, this.ctx.currentTime, 0.1);
    }
  }

  private clearOscillators() {
    [this.oscLeft, this.oscRight].forEach(osc => {
      if (osc) {
        try { osc.stop(); } catch(e) {}
        osc.disconnect();
      }
    });
    this.oscLeft = null;
    this.oscRight = null;
  }

  private createOscillators(startTime: number) {
    if (!this.ctx || !this.masterGain) return;
    this.clearOscillators();

    this.oscLeft = this.ctx.createOscillator();
    this.pannerLeft = this.ctx.createStereoPanner();
    this.pannerLeft.pan.value = -1;

    this.oscRight = this.ctx.createOscillator();
    this.pannerRight = this.ctx.createStereoPanner();
    this.pannerRight.pan.value = 1;

    this.oscLeft.connect(this.pannerLeft);
    if(this.analyserLeft) this.pannerLeft.connect(this.analyserLeft);
    this.pannerLeft.connect(this.masterGain);

    this.oscRight.connect(this.pannerRight);
    if(this.analyserRight) this.pannerRight.connect(this.analyserRight);
    this.pannerRight.connect(this.masterGain);

    const now = this.ctx.currentTime;

    this.events.forEach((evt, index) => {
      const evtTime = now + (evt.timeOffset - startTime);
      const leftFreq = evt.carrierFreq - (evt.beatFreq / 2);
      const rightFreq = evt.carrierFreq + (evt.beatFreq / 2);

      if (evtTime <= now) {
        this.oscLeft?.frequency.setValueAtTime(leftFreq, now);
        this.oscRight?.frequency.setValueAtTime(rightFreq, now);
      } else {
        this.oscLeft?.frequency.linearRampToValueAtTime(leftFreq, evtTime);
        this.oscRight?.frequency.linearRampToValueAtTime(rightFreq, evtTime);
      }
    });

    this.oscLeft.start(now);
    this.oscRight.start(now);
  }

  loadEvents(events: BeatEvent[]) {
    this.events = [...events].sort((a, b) => a.timeOffset - b.timeOffset);
    if (this.isRunning) {
      this.createOscillators(this.getCurrentTime());
    }
  }

  play(offset: number = 0) {
    if (!this.ctx) this.init();
    if (this.ctx?.state === 'suspended') this.ctx.resume();

    this.pausedAt = offset;
    this.createOscillators(offset);
    this.isRunning = true;
    this.playbackStartTime = this.ctx!.currentTime - offset;
  }

  stop() {
    this.clearOscillators();
    this.isRunning = false;
  }

  getCurrentTime(): number {
    if (!this.isRunning || !this.ctx) return this.pausedAt;
    return this.ctx.currentTime - this.playbackStartTime;
  }

  getIsRunning(): boolean {
    return this.isRunning;
  }
}

export const audioEngine = new BinauralAudioEngine();

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { 
  Play, Pause, Upload, Plus, FileCode, Activity, Music, 
  Volume2, Save, Wand2, RefreshCw, Bookmark, Trash2, Wind
} from 'lucide-react';
import { BeatEvent, ViewMode } from './types';
import { parseScript, generateScript } from './services/parser';
import { audioEngine } from './services/audioEngine';
import { Timeline } from './components/Timeline';
import { Visualizer } from './components/Visualizer';
import { EventEditor } from './components/EventEditor';
import { GoogleGenAI } from "@google/genai";

const DEFAULT_SCRIPT = `# Example Binaural Session
# Time  Carrier+Beat/Volume
00:00 200+10/50
01:00 200+8/50
05:00 150+4/60
10:00 150+4/0
`;

interface Preset {
  id: string;
  name: string;
  script: string;
  date: number;
}

function App() {
  const [script, setScript] = useState<string>(DEFAULT_SCRIPT);
  const [events, setEvents] = useState<BeatEvent[]>([]);
  const [isPlaying, setIsPlaying] = useState(false);
  const [viewMode, setViewMode] = useState<ViewMode>(ViewMode.TIMELINE);
  const [currentTime, setCurrentTime] = useState(0);
  const [editingEvent, setEditingEvent] = useState<BeatEvent | null>(null);
  const [aiPrompt, setAiPrompt] = useState("");
  const [isGenerating, setIsGenerating] = useState(false);
  const [volume, setVolume] = useState(50);
  const [noiseLevel, setNoiseLevel] = useState(15);
  const [presets, setPresets] = useState<Preset[]>([]);

  const rafRef = useRef<number>(0);

  // Load presets from localStorage
  useEffect(() => {
    const saved = localStorage.getItem('bf_presets');
    if (saved) {
      try {
        setPresets(JSON.parse(saved));
      } catch (e) {
        console.error("Failed to parse presets", e);
      }
    }
  }, []);

  const saveToPresets = () => {
    const name = prompt("Enter a name for this preset:", "My Session");
    if (!name) return;
    const newPreset: Preset = {
      id: `pre_${Date.now()}`,
      name,
      script,
      date: Date.now()
    };
    const updated = [newPreset, ...presets];
    setPresets(updated);
    localStorage.setItem('bf_presets', JSON.stringify(updated));
  };

  const loadPreset = (p: Preset) => {
    setScript(p.script);
    setCurrentTime(0);
    if (isPlaying) handlePlayToggle();
  };

  const deletePreset = (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    const updated = presets.filter(p => p.id !== id);
    setPresets(updated);
    localStorage.setItem('bf_presets', JSON.stringify(updated));
  };

  // Synchronize script and events
  useEffect(() => {
    const newEvents = parseScript(script);
    setEvents(newEvents);
    audioEngine.loadEvents(newEvents);
  }, [script]);

  const updateScriptFromEvents = useCallback((newEvents: BeatEvent[]) => {
    const sorted = [...newEvents].sort((a,b) => a.timeOffset - b.timeOffset);
    setEvents(sorted);
    setScript(generateScript(sorted));
    audioEngine.loadEvents(sorted);
  }, []);

  const handlePlayToggle = () => {
    if (isPlaying) {
      audioEngine.stop();
      setIsPlaying(false);
      cancelAnimationFrame(rafRef.current);
    } else {
      audioEngine.play(currentTime);
      setIsPlaying(true);

      const updateLoop = () => {
        const time = audioEngine.getCurrentTime();
        setCurrentTime(time);
        rafRef.current = requestAnimationFrame(updateLoop);
      };
      updateLoop();
    }
  };

  const handleSeek = (e: React.ChangeEvent<HTMLInputElement>) => {
    const time = parseFloat(e.target.value);
    setCurrentTime(time);
    if (isPlaying) {
       audioEngine.play(time);
    }
  };

  const handleVolumeChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const val = parseFloat(e.target.value);
    setVolume(val);
    audioEngine.setMasterVolume(val);
  };

  const handleNoiseChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const val = parseFloat(e.target.value);
    setNoiseLevel(val);
    audioEngine.setNoiseLevel(val);
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (evt) => setScript(evt.target?.result as string);
    reader.readAsText(file);
    e.target.value = '';
  };

  const handleDownload = () => {
    const blob = new Blob([script], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'binaural_session.sbg';
    a.click();
    URL.revokeObjectURL(url);
  };

  const handleNewSequence = () => {
    if (window.confirm("Start a new session? Current progress will be lost.")) {
      setScript(`# New Session\n00:00 200+10/50\n`);
      setCurrentTime(0);
      if (isPlaying) handlePlayToggle();
    }
  };

  const handleAddEvent = () => {
    const lastEvent = events[events.length - 1];
    const newTime = lastEvent ? lastEvent.timeOffset + 60 : 0;
    const newEvent: BeatEvent = {
      id: `evt_${Date.now()}`,
      timeOffset: newTime,
      carrierFreq: lastEvent?.carrierFreq || 200,
      beatFreq: lastEvent?.beatFreq || 10,
      volume: lastEvent?.volume || 50
    };
    updateScriptFromEvents([...events, newEvent]);
    setEditingEvent(newEvent);
  };

  const handleEventUpdate = (updated: BeatEvent) => {
    updateScriptFromEvents(events.map(e => e.id === updated.id ? updated : e));
    setEditingEvent(null);
  };

  const handleDeleteEvent = (id: string) => {
    updateScriptFromEvents(events.filter(e => e.id !== id));
  };

  const handleAiGenerate = async () => {
    if (!aiPrompt.trim()) return;
    setIsGenerating(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Create an SBaGen script for: "${aiPrompt}". Format: MM:SS Freq+Beat/Vol. Strictly text only.`,
        config: { systemInstruction: "Expert SBaGen Engineer." }
      });
      if (response.text) {
        setScript(response.text.replace(/```/g, '').trim());
        setAiPrompt("");
      }
    } catch (e) {
      console.error(e);
    } finally {
      setIsGenerating(false);
    }
  };

  const getCurrentValues = () => {
    if (events.length === 0) return { carrier: 0, beat: 0 };
    let startEvt = events[0];
    let endEvt = null;
    for (let i = 0; i < events.length; i++) {
        if (currentTime >= events[i].timeOffset) {
            startEvt = events[i];
            endEvt = events[i+1] || null;
        }
    }
    if (!endEvt) return { carrier: startEvt.carrierFreq, beat: startEvt.beatFreq };
    const progress = (currentTime - startEvt.timeOffset) / (endEvt.timeOffset - startEvt.timeOffset);
    return {
      carrier: startEvt.carrierFreq + (endEvt.carrierFreq - startEvt.carrierFreq) * progress,
      beat: startEvt.beatFreq + (endEvt.beatFreq - startEvt.beatFreq) * progress
    };
  };

  const { carrier: liveCarrier, beat: liveBeat } = getCurrentValues();
  const totalDuration = events.length > 0 ? events[events.length - 1].timeOffset + 60 : 600;

  return (
    <div className="min-h-screen bg-gray-950 text-gray-200 font-sans flex flex-col selection:bg-accent-500/30">
      <header className="bg-gray-900 border-b border-gray-800 p-4 flex items-center justify-between sticky top-0 z-40 backdrop-blur-md bg-opacity-80">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 bg-accent-600 rounded-lg flex items-center justify-center shadow-lg shadow-accent-900/50 transition-transform hover:scale-105">
             <Activity className="text-white" />
          </div>
          <div>
            <h1 className="text-xl font-bold text-white tracking-tight">BinauralForge</h1>
            <p className="text-[10px] text-gray-500 font-mono uppercase tracking-widest">v2.1 Masterwork</p>
          </div>
        </div>

        <div className="flex items-center gap-3">
           <div className="flex bg-gray-800 rounded-lg p-1 border border-gray-700">
             <button onClick={() => setViewMode(ViewMode.TIMELINE)} className={`p-2 rounded transition-all ${viewMode === ViewMode.TIMELINE ? 'bg-gray-700 text-white shadow-inner' : 'text-gray-400 hover:text-white'}`}><Music size={18} /></button>
             <button onClick={() => setViewMode(ViewMode.SCRIPT)} className={`p-2 rounded transition-all ${viewMode === ViewMode.SCRIPT ? 'bg-gray-700 text-white shadow-inner' : 'text-gray-400 hover:text-white'}`}><FileCode size={18} /></button>
           </div>
           <div className="h-6 w-px bg-gray-800 mx-1" />
           <button onClick={saveToPresets} className="bg-gray-800 hover:bg-gray-700 text-gray-300 px-3 py-2 rounded border border-gray-700 transition-all text-sm flex items-center gap-2" title="Save to Presets"><Bookmark size={14} /><span className="hidden sm:inline">Save Preset</span></button>
           <label className="cursor-pointer bg-gray-800 hover:bg-gray-700 text-gray-300 px-3 py-2 rounded border border-gray-700 transition-all text-sm flex items-center gap-2"><Upload size={14} /><span className="hidden sm:inline">Load File</span><input type="file" className="hidden" accept=".sbg,.txt" onChange={handleFileUpload} /></label>
           <button onClick={handleDownload} className="bg-accent-600 hover:bg-accent-500 text-white px-3 py-2 rounded border border-accent-500 transition-all text-sm flex items-center gap-2"><Save size={14} /><span className="hidden sm:inline">Export</span></button>
        </div>
      </header>

      <main className="flex-1 flex flex-col p-6 gap-6 max-w-7xl mx-auto w-full">
        <div className="grid grid-cols-1 lg:grid-cols-4 gap-6">
           {/* Controls Column */}
           <div className="lg:col-span-3 space-y-4">
              <Visualizer isPlaying={isPlaying} />
              <div className="bg-gray-900 rounded-xl p-4 border border-gray-800 shadow-2xl flex items-center gap-4">
                 <button onClick={handlePlayToggle} className={`w-14 h-14 rounded-full flex items-center justify-center transition-all transform hover:scale-105 active:scale-95 ${isPlaying ? 'bg-red-500 hover:bg-red-600 shadow-lg shadow-red-900/40' : 'bg-green-500 hover:bg-green-600 shadow-lg shadow-green-900/40'} text-white`}>
                    {isPlaying ? <Pause size={24} fill="currentColor" /> : <Play size={24} fill="currentColor" className="ml-1" />}
                 </button>
                 <div className="flex-1 px-2">
                    <div className="flex justify-between text-[10px] font-mono text-gray-500 mb-2 uppercase tracking-tighter">
                       <span>{new Date(currentTime * 1000).toISOString().substr(14, 5)}</span>
                       <span className="text-gray-400">Master Seek</span>
                       <span>{new Date(totalDuration * 1000).toISOString().substr(14, 5)}</span>
                    </div>
                    <input type="range" min="0" max={totalDuration} value={currentTime} onChange={handleSeek} className="w-full h-1.5 bg-gray-800 rounded-lg appearance-none cursor-pointer accent-accent-500" />
                 </div>

                 <div className="flex flex-col gap-2 w-48 bg-gray-800/50 p-3 rounded-lg border border-gray-700">
                    <div className="flex items-center gap-3 text-gray-400">
                       <Volume2 size={14} />
                       <input type="range" min="0" max="100" value={volume} onChange={handleVolumeChange} className="w-full h-1 bg-gray-700 rounded-lg appearance-none cursor-pointer accent-gray-400" />
                    </div>
                    <div className="flex items-center gap-3 text-gray-400">
                       <Wind size={14} />
                       <input type="range" min="0" max="50" value={noiseLevel} onChange={handleNoiseChange} className="w-full h-1 bg-gray-700 rounded-lg appearance-none cursor-pointer accent-gray-400" />
                    </div>
                 </div>
              </div>
           </div>

           {/* Presets / History Column */}
           <div className="bg-gray-900 rounded-xl p-5 border border-gray-800 shadow-xl flex flex-col gap-4 max-h-[220px] lg:max-h-none overflow-hidden">
              <h3 className="text-gray-500 uppercase tracking-widest text-[10px] font-bold border-b border-gray-800 pb-2">Your Sessions</h3>
              <div className="flex-1 overflow-y-auto space-y-2 pr-2 custom-scrollbar">
                 {presets.length === 0 ? (
                    <div className="text-xs text-gray-600 italic py-4 text-center">No saved presets yet.</div>
                 ) : (
                    presets.map(p => (
                       <div key={p.id} onClick={() => loadPreset(p)} className="group flex items-center justify-between bg-gray-850 hover:bg-gray-800 p-2 rounded border border-gray-800 cursor-pointer transition-colors">
                          <div className="overflow-hidden">
                             <div className="text-xs font-semibold truncate text-gray-300">{p.name}</div>
                             <div className="text-[9px] text-gray-500 font-mono">{new Date(p.date).toLocaleDateString()}</div>
                          </div>
                          <button onClick={(e) => deletePreset(p.id, e)} className="p-1 opacity-0 group-hover:opacity-100 text-gray-500 hover:text-red-400 transition-all"><Trash2 size={12} /></button>
                       </div>
                    ))
                 )}
              </div>
           </div>
        </div>

        {/* AI Prompt Section */}
        <div className="bg-gradient-to-r from-gray-900 to-gray-850 rounded-xl p-1 border border-gray-700/50 shadow-inner group">
           <div className="flex flex-col sm:flex-row gap-2 p-2">
              <div className="flex-1 relative">
                 <input type="text" placeholder="AI Architect: e.g. 'Concentration flow starting at 12Hz, peaking at 15Hz beta for 10 mins'" className="w-full bg-gray-950 border border-gray-700 rounded-lg px-4 py-3 text-gray-200 focus:ring-2 focus:ring-accent-500 outline-none text-sm placeholder-gray-600 font-mono transition-all" value={aiPrompt} onChange={(e) => setAiPrompt(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && handleAiGenerate()} />
                 <Wand2 className="absolute right-4 top-1/2 -translate-y-1/2 text-gray-700 group-hover:text-accent-500 transition-colors" size={18} />
              </div>
              <button onClick={handleAiGenerate} disabled={isGenerating || !aiPrompt.trim()} className="bg-accent-600 hover:bg-accent-500 disabled:opacity-50 text-white px-6 py-3 rounded-lg text-sm font-bold flex items-center justify-center gap-2 transition-all shadow-xl shadow-accent-900/20">
                 {isGenerating ? <span className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin" /> : <Wand2 size={16} />}
                 <span className="hidden md:inline">Forge Session</span>
              </button>
           </div>
        </div>

        <div className="flex-1 min-h-[600px] bg-gray-900 rounded-xl border border-gray-800 shadow-2xl overflow-hidden relative flex flex-col">
           {viewMode === ViewMode.TIMELINE ? (
             <div className="flex flex-col h-full">
                <div className="w-full p-6 flex-none border-b border-gray-800 bg-gray-900/50 backdrop-blur-sm">
                    <div className="flex justify-between items-start mb-6">
                       <div>
                           <h2 className="text-lg font-bold text-white tracking-tight flex items-center gap-2"><Music size={18} className="text-accent-500" /> Sequence Timeline</h2>
                           <div className="mt-4 p-4 bg-gray-950 rounded-xl border border-gray-800 inline-flex items-center gap-4 shadow-inner">
                               <div className="flex flex-col">
                                  <span className="text-[10px] text-gray-500 uppercase font-bold tracking-widest">Target Beat</span>
                                  <span className="text-4xl font-mono font-bold text-accent-400 tabular-nums leading-none">{liveBeat.toFixed(2)}<span className="text-sm text-gray-600 ml-1 font-sans">Hz</span></span>
                               </div>
                               <div className="w-px h-10 bg-gray-800" />
                               <div className="flex flex-col">
                                  <span className="text-[10px] text-gray-500 uppercase font-bold tracking-widest">Base Carrier</span>
                                  <span className="text-2xl font-mono text-gray-400 tabular-nums leading-none">{liveCarrier.toFixed(0)}<span className="text-xs text-gray-700 ml-1 font-sans">Hz</span></span>
                               </div>
                           </div>
                       </div>
                       <div className="flex gap-2">
                          <button onClick={handleNewSequence} className="bg-gray-800 hover:bg-red-900/20 hover:text-red-400 text-gray-300 px-4 py-2 rounded-lg text-sm font-bold flex items-center gap-2 transition-all border border-gray-700"><RefreshCw size={16} /> Reset</button>
                          <button onClick={handleAddEvent} className="bg-accent-600 hover:bg-accent-500 text-white px-4 py-2 rounded-lg text-sm font-bold flex items-center gap-2 transition-all border border-accent-500 shadow-lg"><Plus size={18} /> New Event</button>
                       </div>
                    </div>
                    <div className="relative pt-2">
                       <Timeline events={events} duration={totalDuration} onEventClick={setEditingEvent} onDeleteEvent={handleDeleteEvent} playbackTime={currentTime} />
                    </div>
                </div>

                <div className="w-full flex-1 flex flex-col bg-gray-950/30">
                    <div className="p-3 border-b border-gray-800 bg-gray-900/30 backdrop-blur text-[10px] text-gray-500 font-bold uppercase tracking-widest flex items-center gap-2">
                       <FileCode size={14} className="text-accent-500" /> SBaGen Script Stream
                    </div>
                    <textarea value={script} onChange={(e) => setScript(e.target.value)} className="flex-1 w-full bg-transparent text-gray-500 font-mono text-xs p-6 resize-none focus:outline-none focus:bg-gray-950/50 transition-all leading-relaxed border-none selection:bg-accent-500/20" spellCheck={false} placeholder="Script updates here..." />
                </div>
             </div>
           ) : (
             <div className="flex flex-col h-full">
                <div className="bg-gray-850 px-6 py-3 border-b border-gray-800 text-xs text-gray-400 flex justify-between items-center">
                   <span className="font-mono flex items-center gap-2"><FileCode size={14} /> editor.sbg</span>
                   <span className="bg-gray-700 px-2 py-0.5 rounded text-[10px] text-gray-300">RAW MODE</span>
                </div>
                <textarea value={script} onChange={(e) => setScript(e.target.value)} className="flex-1 bg-gray-950 text-gray-300 font-mono p-8 outline-none resize-none text-sm leading-relaxed" spellCheck={false} />
             </div>
           )}
        </div>
      </main>

      <footer className="p-4 border-t border-gray-800 bg-gray-900 text-center flex items-center justify-between px-10">
         <p className="text-[10px] text-gray-600 font-mono uppercase tracking-widest">BinauralForge Pro • Ambient Engine Active</p>
         <div className="flex gap-4 text-[10px] text-gray-600 font-mono uppercase tracking-widest">
            <span className="hover:text-accent-400 cursor-help transition-colors">Documentation</span>
            <span className="hover:text-accent-400 cursor-help transition-colors">SBaGen Wiki</span>
         </div>
      </footer>

      <EventEditor event={editingEvent} onSave={handleEventUpdate} onCancel={() => setEditingEvent(null)} />
    </div>
  );
}

export default App;

export interface BeatEvent {
  id: string;
  timeOffset: number; // in seconds
  carrierFreq: number; // Hz
  beatFreq: number; // Hz
  volume: number; // 0-100
  fadeType?: 'linear' | 'exponential';
}

export enum NoiseType {
  OFF = 'OFF',
  WHITE = 'WHITE',
  PINK = 'PINK',
  BROWN = 'BROWN',
}

export interface PlaybackState {
  isPlaying: boolean;
  currentTime: number; // seconds
  totalDuration: number; // seconds
  analyserDataLeft: Uint8Array;
  analyserDataRight: Uint8Array;
}

export enum ViewMode {
  TIMELINE = 'TIMELINE',
  SCRIPT = 'SCRIPT',
  FOCUS = 'FOCUS',
}

import { BeatEvent, NoiseType } from '../types';

class BinauralAudioEngine {
  private ctx: AudioContext | null = null;
  private masterGain: GainNode | null = null;

  // Binaural Oscillators
  private oscLeft: OscillatorNode | null = null;
  private oscRight: OscillatorNode | null = null;
  private pannerLeft: StereoPannerNode | null = null;
  private pannerRight: StereoPannerNode | null = null;

  // Noise Generator
  private noiseNode: ScriptProcessorNode | null = null;
  private noiseGain: GainNode | null = null;
  private currentNoiseType: NoiseType = NoiseType.PINK;

  // LFO for organic drifting
  private lfo: OscillatorNode | null = null;
  private lfoGain: GainNode | null = null;

  // Analysis
  public analyserLeft: AnalyserNode | null = null;
  public analyserRight: AnalyserNode | null = null;

  private isRunning: boolean = false;
  private events: BeatEvent[] = [];
  private playbackStartTime: number = 0;
  private pausedAt: number = 0;
  private masterVolume: number = 0.5;
  private noiseLevel: number = 0.15;

  constructor() {}

  init() {
    if (this.ctx) return;
    this.ctx = new (window.AudioContext || (window as any).webkitAudioContext)();
    this.masterGain = this.ctx.createGain();
    this.masterGain.connect(this.ctx.destination);
    this.masterGain.gain.value = this.masterVolume;

    this.analyserLeft = this.ctx.createAnalyser();
    this.analyserRight = this.ctx.createAnalyser();
    this.analyserLeft.fftSize = 512;
    this.analyserRight.fftSize = 512;

    this.setupNoise();
    this.setupLFO();
  }

  private setupLFO() {
    if (!this.ctx || !this.masterGain) return;
    this.lfo = this.ctx.createOscillator();
    this.lfoGain = this.ctx.createGain();
    this.lfo.frequency.value = 0.08; 
    this.lfoGain.gain.value = 0.03;
    this.lfo.connect(this.lfoGain);
    this.lfo.start();
  }

  private setupNoise() {
    if (!this.ctx || !this.masterGain) return;

    const bufferSize = 4096;
    // States for pink noise
    let b0, b1, b2, b3, b4, b5, b6;
    b0 = b1 = b2 = b3 = b4 = b5 = b6 = 0.0;
    // State for brown noise
    let lastOut = 0.0;

    const node = this.ctx.createScriptProcessor(bufferSize, 1, 1);
    node.onaudioprocess = (e) => {
      const output = e.outputBuffer.getChannelData(0);
      for (let i = 0; i < bufferSize; i++) {
        const white = Math.random() * 2 - 1;

        if (this.currentNoiseType === NoiseType.WHITE) {
          output[i] = white * 0.1;
        } else if (this.currentNoiseType === NoiseType.PINK) {
          b0 = 0.99886 * b0 + white * 0.0555179;
          b1 = 0.99332 * b1 + white * 0.0750759;
          b2 = 0.96900 * b2 + white * 0.1538520;
          b3 = 0.86650 * b3 + white * 0.3104856;
          b4 = 0.55000 * b4 + white * 0.5329522;
          b5 = -0.7616 * b5 - white * 0.0168980;
          output[i] = b0 + b1 + b2 + b3 + b4 + b5 + b6 + white * 0.5362;
          output[i] *= 0.11;
          b6 = white * 0.115926;
        } else if (this.currentNoiseType === NoiseType.BROWN) {
          output[i] = (lastOut + (0.02 * white)) / 1.02;
          lastOut = output[i];
          output[i] *= 3.5; // Gain compensation
        } else {
          output[i] = 0;
        }
      }
    };

    this.noiseGain = this.ctx.createGain();
    this.noiseGain.gain.value = this.currentNoiseType === NoiseType.OFF ? 0 : this.noiseLevel;
    node.connect(this.noiseGain);
    this.noiseGain.connect(this.masterGain);
    this.noiseNode = node;
  }

  setNoiseType(type: NoiseType) {
    this.currentNoiseType = type;
    if (this.noiseGain && this.ctx) {
      const target = type === NoiseType.OFF ? 0 : this.noiseLevel;
      this.noiseGain.gain.setTargetAtTime(target, this.ctx.currentTime, 0.1);
    }
  }

  setMasterVolume(percent: number) {
    this.masterVolume = Math.max(0, Math.min(1, percent / 100));
    if (this.masterGain && this.ctx) {
      this.masterGain.gain.setTargetAtTime(this.masterVolume, this.ctx.currentTime, 0.05);
    }
  }

  setNoiseLevel(percent: number) {
    this.noiseLevel = Math.max(0, Math.min(1, percent / 100));
    if (this.noiseGain && this.ctx && this.currentNoiseType !== NoiseType.OFF) {
      this.noiseGain.gain.setTargetAtTime(this.noiseLevel, this.ctx.currentTime, 0.1);
    }
  }

  private clearOscillators() {
    [this.oscLeft, this.oscRight].forEach(osc => {
      if (osc) {
        try { osc.stop(); } catch(e) {}
        osc.disconnect();
      }
    });
    this.oscLeft = null;
    this.oscRight = null;
  }

  private createOscillators(startTime: number) {
    if (!this.ctx || !this.masterGain) return;
    this.clearOscillators();

    this.oscLeft = this.ctx.createOscillator();
    this.pannerLeft = this.ctx.createStereoPanner();
    this.pannerLeft.pan.value = -1;

    this.oscRight = this.ctx.createOscillator();
    this.pannerRight = this.ctx.createStereoPanner();
    this.pannerRight.pan.value = 1;

    this.oscLeft.connect(this.pannerLeft);
    if(this.analyserLeft) this.pannerLeft.connect(this.analyserLeft);
    this.pannerLeft.connect(this.masterGain);

    this.oscRight.connect(this.pannerRight);
    if(this.analyserRight) this.pannerRight.connect(this.analyserRight);
    this.pannerRight.connect(this.masterGain);

    const now = this.ctx.currentTime;

    this.events.forEach((evt, index) => {
      const evtTime = now + (evt.timeOffset - startTime);
      const leftFreq = evt.carrierFreq - (evt.beatFreq / 2);
      const rightFreq = evt.carrierFreq + (evt.beatFreq / 2);

      if (evtTime <= now) {
        this.oscLeft?.frequency.setValueAtTime(leftFreq, now);
        this.oscRight?.frequency.setValueAtTime(rightFreq, now);
      } else {
        this.oscLeft?.frequency.linearRampToValueAtTime(leftFreq, evtTime);
        this.oscRight?.frequency.linearRampToValueAtTime(rightFreq, evtTime);
      }
    });

    this.oscLeft.start(now);
    this.oscRight.start(now);
  }

  loadEvents(events: BeatEvent[]) {
    this.events = [...events].sort((a, b) => a.timeOffset - b.timeOffset);
    if (this.isRunning) {
      this.createOscillators(this.getCurrentTime());
    }
  }

  play(offset: number = 0) {
    if (!this.ctx) this.init();
    if (this.ctx?.state === 'suspended') this.ctx.resume();

    this.pausedAt = offset;
    this.createOscillators(offset);
    this.isRunning = true;
    this.playbackStartTime = this.ctx!.currentTime - offset;
  }

  stop() {
    this.clearOscillators();
    this.isRunning = false;
  }

  getCurrentTime(): number {
    if (!this.isRunning || !this.ctx) return this.pausedAt;
    return this.ctx.currentTime - this.playbackStartTime;
  }

  getIsRunning(): boolean {
    return this.isRunning;
  }
}

export const audioEngine = new BinauralAudioEngine();

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { 
  Play, Pause, Upload, Plus, FileCode, Activity, Music, 
  Volume2, Save, Wand2, RefreshCw, Bookmark, Trash2, Wind,
  Share2, Maximize2, Minimize2, Settings2
} from 'lucide-react';
import { BeatEvent, ViewMode, NoiseType } from './types';
import { parseScript, generateScript } from './services/parser';
import { audioEngine } from './services/audioEngine';
import { Timeline } from './components/Timeline';
import { Visualizer } from './components/Visualizer';
import { EventEditor } from './components/EventEditor';
import { GoogleGenAI } from "@google/genai";

const DEFAULT_SCRIPT = `# Example Binaural Session
# Time  Carrier+Beat/Volume
00:00 200+10/50
01:00 200+8/50
05:00 150+4/60
10:00 150+4/0
`;

interface Preset {
  id: string;
  name: string;
  script: string;
  date: number;
}

function App() {
  const [script, setScript] = useState<string>(DEFAULT_SCRIPT);
  const [events, setEvents] = useState<BeatEvent[]>([]);
  const [isPlaying, setIsPlaying] = useState(false);
  const [viewMode, setViewMode] = useState<ViewMode>(ViewMode.TIMELINE);
  const [currentTime, setCurrentTime] = useState(0);
  const [editingEvent, setEditingEvent] = useState<BeatEvent | null>(null);
  const [aiPrompt, setAiPrompt] = useState("");
  const [isGenerating, setIsGenerating] = useState(false);
  const [volume, setVolume] = useState(50);
  const [noiseLevel, setNoiseLevel] = useState(15);
  const [noiseType, setNoiseType] = useState<NoiseType>(NoiseType.PINK);
  const [presets, setPresets] = useState<Preset[]>([]);

  const rafRef = useRef<number>(0);

  // Load presets and check URL for shared scripts
  useEffect(() => {
    const saved = localStorage.getItem('bf_presets');
    if (saved) {
      try { setPresets(JSON.parse(saved)); } catch (e) {}
    }

    const urlParams = new URLSearchParams(window.location.search);
    const shared = urlParams.get('s');
    if (shared) {
      try {
        const decoded = atob(shared);
        setScript(decoded);
        window.history.replaceState({}, document.title, window.location.pathname);
      } catch (e) {}
    }
  }, []);

  const saveToPresets = () => {
    const name = prompt("Enter a name for this preset:", "My Session");
    if (!name) return;
    const newPreset: Preset = { id: `pre_${Date.now()}`, name, script, date: Date.now() };
    const updated = [newPreset, ...presets];
    setPresets(updated);
    localStorage.setItem('bf_presets', JSON.stringify(updated));
  };

  const handleShare = () => {
    const encoded = btoa(script);
    const url = `${window.location.origin}${window.location.pathname}?s=${encoded}`;
    navigator.clipboard.writeText(url).then(() => {
      alert("Shareable link copied to clipboard!");
    });
  };

  const loadPreset = (p: Preset) => {
    setScript(p.script);
    setCurrentTime(0);
    if (isPlaying) handlePlayToggle();
  };

  const deletePreset = (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    const updated = presets.filter(p => p.id !== id);
    setPresets(updated);
    localStorage.setItem('bf_presets', JSON.stringify(updated));
  };

  useEffect(() => {
    const newEvents = parseScript(script);
    setEvents(newEvents);
    audioEngine.loadEvents(newEvents);
  }, [script]);

  const updateScriptFromEvents = useCallback((newEvents: BeatEvent[]) => {
    const sorted = [...newEvents].sort((a,b) => a.timeOffset - b.timeOffset);
    setEvents(sorted);
    setScript(generateScript(sorted));
    audioEngine.loadEvents(sorted);
  }, []);

  const handlePlayToggle = () => {
    if (isPlaying) {
      audioEngine.stop();
      setIsPlaying(false);
      cancelAnimationFrame(rafRef.current);
    } else {
      audioEngine.play(currentTime);
      setIsPlaying(true);
      const updateLoop = () => {
        setCurrentTime(audioEngine.getCurrentTime());
        rafRef.current = requestAnimationFrame(updateLoop);
      };
      updateLoop();
    }
  };

  const handleSeek = (e: React.ChangeEvent<HTMLInputElement>) => {
    const time = parseFloat(e.target.value);
    setCurrentTime(time);
    if (isPlaying) audioEngine.play(time);
  };

  const handleVolumeChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const val = parseFloat(e.target.value);
    setVolume(val);
    audioEngine.setMasterVolume(val);
  };

  const handleNoiseChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const val = parseFloat(e.target.value);
    setNoiseLevel(val);
    audioEngine.setNoiseLevel(val);
  };

  const handleNoiseTypeChange = (type: NoiseType) => {
    setNoiseType(type);
    audioEngine.setNoiseType(type);
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (evt) => setScript(evt.target?.result as string);
    reader.readAsText(file);
    e.target.value = '';
  };

  const handleDownload = () => {
    const blob = new Blob([script], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'binaural_session.sbg';
    a.click();
    URL.revokeObjectURL(url);
  };

  const handleNewSequence = () => {
    if (window.confirm("Start a new session?")) {
      setScript(`# New Session\n00:00 200+10/50\n`);
      setCurrentTime(0);
      if (isPlaying) handlePlayToggle();
    }
  };

  const handleAddEvent = () => {
    const lastEvent = events[events.length - 1];
    const newTime = lastEvent ? lastEvent.timeOffset + 60 : 0;
    const newEvent: BeatEvent = {
      id: `evt_${Date.now()}`,
      timeOffset: newTime,
      carrierFreq: lastEvent?.carrierFreq || 200,
      beatFreq: lastEvent?.beatFreq || 10,
      volume: lastEvent?.volume || 50
    };
    updateScriptFromEvents([...events, newEvent]);
    setEditingEvent(newEvent);
  };

  const handleEventUpdate = (updated: BeatEvent) => {
    updateScriptFromEvents(events.map(e => e.id === updated.id ? updated : e));
    setEditingEvent(null);
  };

  const handleDeleteEvent = (id: string) => {
    updateScriptFromEvents(events.filter(e => e.id !== id));
  };

  const handleAiGenerate = async () => {
    if (!aiPrompt.trim()) return;
    setIsGenerating(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Create an SBaGen script for: "${aiPrompt}". Format: MM:SS Freq+Beat/Vol. Strictly text only. Include a short comment explaining the frequency choice.`,
        config: { systemInstruction: "Professional Audio DSP Engineer specialized in binaural neuro-acoustics." }
      });
      if (response.text) {
        setScript(response.text.replace(/```/g, '').trim());
        setAiPrompt("");
      }
    } catch (e) {
      console.error(e);
    } finally { setIsGenerating(false); }
  };

  const getCurrentValues = () => {
    if (events.length === 0) return { carrier: 0, beat: 0 };
    let startEvt = events[0];
    let endEvt = null;
    for (let i = 0; i < events.length; i++) {
        if (currentTime >= events[i].timeOffset) {
            startEvt = events[i];
            endEvt = events[i+1] || null;
        }
    }
    if (!endEvt) return { carrier: startEvt.carrierFreq, beat: startEvt.beatFreq };
    const progress = (currentTime - startEvt.timeOffset) / (endEvt.timeOffset - startEvt.timeOffset);
    return {
      carrier: startEvt.carrierFreq + (endEvt.carrierFreq - startEvt.carrierFreq) * progress,
      beat: startEvt.beatFreq + (endEvt.beatFreq - startEvt.beatFreq) * progress
    };
  };

  const { carrier: liveCarrier, beat: liveBeat } = getCurrentValues();
  const totalDuration = events.length > 0 ? events[events.length - 1].timeOffset + 60 : 600;

  if (viewMode === ViewMode.FOCUS) {
    return (
      <div className="fixed inset-0 bg-gray-950 flex flex-col items-center justify-center p-8 transition-all animate-in fade-in duration-1000">
         <div className="absolute top-8 left-8 flex items-center gap-3">
            <Activity className="text-accent-500 animate-pulse" />
            <h1 className="text-xl font-bold tracking-tighter text-white opacity-40">BinauralForge Focus</h1>
         </div>
         <button onClick={() => setViewMode(ViewMode.TIMELINE)} className="absolute top-8 right-8 p-3 bg-gray-900 border border-gray-800 rounded-full text-gray-500 hover:text-white transition-all"><Minimize2 size={24} /></button>

         <div className="w-full max-w-2xl space-y-12 text-center">
            <div className="w-full h-48">
              <Visualizer isPlaying={isPlaying} />
            </div>

            <div className="space-y-4">
              <div className="text-7xl font-mono font-bold text-accent-400 tabular-nums">
                 {liveBeat.toFixed(2)}<span className="text-xl text-gray-700 ml-2">Hz</span>
              </div>
              <div className="text-sm text-gray-500 uppercase tracking-widest font-bold">Current Entrainment Target</div>
            </div>

            <div className="flex items-center justify-center gap-8">
               <button onClick={handlePlayToggle} className={`w-24 h-24 rounded-full flex items-center justify-center transition-all transform hover:scale-105 active:scale-95 ${isPlaying ? 'bg-red-500/20 text-red-400 border border-red-500/40' : 'bg-accent-600 text-white shadow-2xl shadow-accent-900/50'}`}>
                  {isPlaying ? <Pause size={40} fill="currentColor" /> : <Play size={40} fill="currentColor" className="ml-2" />}
               </button>
               <div className="flex flex-col items-start gap-2 w-48">
                  <div className="flex items-center gap-3 w-full text-gray-500"><Volume2 size={16} /><input type="range" min="0" max="100" value={volume} onChange={handleVolumeChange} className="w-full h-1 bg-gray-800 rounded-lg appearance-none cursor-pointer accent-accent-500" /></div>
                  <div className="flex items-center gap-3 w-full text-gray-500"><Wind size={16} /><input type="range" min="0" max="50" value={noiseLevel} onChange={handleNoiseChange} className="w-full h-1 bg-gray-800 rounded-lg appearance-none cursor-pointer accent-accent-500" /></div>
               </div>
            </div>
         </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-950 text-gray-200 font-sans flex flex-col selection:bg-accent-500/30">
      <header className="bg-gray-900 border-b border-gray-800 p-4 flex items-center justify-between sticky top-0 z-40 backdrop-blur-md bg-opacity-80">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 bg-accent-600 rounded-lg flex items-center justify-center shadow-lg shadow-accent-900/50 transition-transform hover:scale-105">
             <Activity className="text-white" />
          </div>
          <div>
            <h1 className="text-xl font-bold text-white tracking-tight">BinauralForge</h1>
            <p className="text-[10px] text-gray-500 font-mono uppercase tracking-widest">v2.2 Immersion</p>
          </div>
        </div>

        <div className="flex items-center gap-2">
           <div className="flex bg-gray-800 rounded-lg p-1 border border-gray-700">
             <button onClick={() => setViewMode(ViewMode.TIMELINE)} className={`p-2 rounded transition-all ${viewMode === ViewMode.TIMELINE ? 'bg-gray-700 text-white' : 'text-gray-400 hover:text-white'}`}><Music size={18} /></button>
             <button onClick={() => setViewMode(ViewMode.SCRIPT)} className={`p-2 rounded transition-all ${viewMode === ViewMode.SCRIPT ? 'bg-gray-700 text-white' : 'text-gray-400 hover:text-white'}`}><FileCode size={18} /></button>
             <button onClick={() => setViewMode(ViewMode.FOCUS)} className="p-2 rounded text-gray-400 hover:text-white transition-all"><Maximize2 size={18} /></button>
           </div>
           <div className="h-6 w-px bg-gray-800 mx-1" />
           <button onClick={handleShare} className="bg-gray-800 hover:bg-gray-700 text-gray-300 p-2 rounded border border-gray-700 transition-all" title="Share Session"><Share2 size={18} /></button>
           <button onClick={saveToPresets} className="bg-gray-800 hover:bg-gray-700 text-gray-300 p-2 rounded border border-gray-700 transition-all" title="Save Preset"><Bookmark size={18} /></button>
           <button onClick={handleDownload} className="bg-accent-600 hover:bg-accent-500 text-white px-3 py-2 rounded border border-accent-500 transition-all text-sm font-bold flex items-center gap-2"><Save size={16} /><span className="hidden sm:inline">Export</span></button>
        </div>
      </header>

      <main className="flex-1 flex flex-col p-6 gap-6 max-w-7xl mx-auto w-full">
        <div className="grid grid-cols-1 lg:grid-cols-4 gap-6">
           <div className="lg:col-span-3 space-y-4">
              <Visualizer isPlaying={isPlaying} />
              <div className="bg-gray-900 rounded-xl p-4 border border-gray-800 shadow-2xl flex items-center gap-4">
                 <button onClick={handlePlayToggle} className={`w-14 h-14 rounded-full flex items-center justify-center transition-all transform hover:scale-105 active:scale-95 ${isPlaying ? 'bg-red-500 hover:bg-red-600' : 'bg-green-500 hover:bg-green-600'} text-white shadow-xl`}>
                    {isPlaying ? <Pause size={24} fill="currentColor" /> : <Play size={24} fill="currentColor" className="ml-1" />}
                 </button>
                 <div className="flex-1 px-2">
                    <div className="flex justify-between text-[10px] font-mono text-gray-500 mb-2 uppercase tracking-tighter">
                       <span>{new Date(currentTime * 1000).toISOString().substr(14, 5)}</span>
                       <span className="text-gray-400">Master Sequence</span>
                       <span>{new Date(totalDuration * 1000).toISOString().substr(14, 5)}</span>
                    </div>
                    <input type="range" min="0" max={totalDuration} value={currentTime} onChange={handleSeek} className="w-full h-1.5 bg-gray-800 rounded-lg appearance-none cursor-pointer accent-accent-500" />
                 </div>

                 <div className="flex flex-col gap-3 w-56 bg-gray-800/40 p-3 rounded-lg border border-gray-700">
                    <div className="flex items-center gap-3 text-gray-400">
                       <Volume2 size={14} />
                       <input type="range" min="0" max="100" value={volume} onChange={handleVolumeChange} className="w-full h-1 bg-gray-700 rounded-lg appearance-none cursor-pointer accent-gray-400" />
                    </div>
                    <div className="flex items-center gap-3">
                       <Wind size={14} className="text-gray-500" />
                       <div className="flex-1 flex gap-1">
                          {[NoiseType.WHITE, NoiseType.PINK, NoiseType.BROWN].map(t => (
                            <button 
                              key={t} 
                              onClick={() => handleNoiseTypeChange(t)}
                              className={`flex-1 text-[9px] font-bold py-1 rounded transition-all ${noiseType === t ? 'bg-accent-600 text-white' : 'bg-gray-700 text-gray-400 hover:bg-gray-600'}`}
                            >
                              {t}
                            </button>
                          ))}
                          <button onClick={() => handleNoiseTypeChange(NoiseType.OFF)} className={`flex-1 text-[9px] font-bold py-1 rounded transition-all ${noiseType === NoiseType.OFF ? 'bg-red-900/40 text-red-400' : 'bg-gray-700 text-gray-400 hover:bg-gray-600'}`}>OFF</button>
                       </div>
                    </div>
                 </div>
              </div>
           </div>

           <div className="bg-gray-900 rounded-xl p-5 border border-gray-800 shadow-xl flex flex-col gap-4 overflow-hidden">
              <div className="flex justify-between items-center border-b border-gray-800 pb-2">
