                       <div className="truncate flex-1 pr-2">
                          <div className="text-xs font-bold truncate text-gray-300">{p.name}</div>
                          <div className="text-[9px] text-gray-500 font-mono italic">{new Date(p.date).toLocaleDateString()}</div>
                       </div>
                       <button onClick={(e) => deletePreset(p.id, e)} className="p-1 opacity-0 group-hover:opacity-100 text-gray-500 hover:text-red-400 transition-all"><Trash2 size={12} /></button>
