           </div>
        </div>

        <div className="flex-1 min-h-[600px] bg-gray-900 rounded-xl border border-gray-800 shadow-2xl overflow-hidden flex flex-col relative group">
           {viewMode === ViewMode.TIMELINE ? (
             <div className="flex flex-col h-full">
                <div className="w-full p-6 flex-none border-b border-gray-800 bg-gray-900/40">
                    <div className="flex justify-between items-start mb-6">
                       <div>
                           <h2 className="text-lg font-bold text-white tracking-tight flex items-center gap-2"><Music size={18} className="text-accent-500" /> Sequence Architecture</h2>
                           <div className="mt-4 flex gap-4">
                              <div className="p-4 bg-gray-950 rounded-xl border border-gray-800 shadow-inner min-w-[140px]">
                                 <span className="text-[10px] text-gray-600 uppercase font-bold tracking-widest block mb-1">Beat Rate</span>
                                 <span className="text-4xl font-mono font-bold text-accent-400 tabular-nums leading-none">{liveBeat.toFixed(2)}<span className="text-sm text-gray-700 ml-1 font-sans font-normal">Hz</span></span>
                              </div>
                              <div className="p-4 bg-gray-950 rounded-xl border border-gray-800 shadow-inner min-w-[120px]">
                                 <span className="text-[10px] text-gray-600 uppercase font-bold tracking-widest block mb-1">Carrier</span>
                                 <span className="text-2xl font-mono text-gray-500 tabular-nums leading-none">{liveCarrier.toFixed(0)}<span className="text-xs text-gray-700 ml-1 font-sans font-normal">Hz</span></span>
                              </div>
                           </div>
                       </div>
                       <div className="flex gap-2">
                          <button onClick={handleNewSequence} className="bg-gray-800 hover:bg-red-900/20 hover:text-red-400 text-gray-400 px-4 py-2 rounded-lg text-sm font-bold flex items-center gap-2 transition-all border border-gray-700"><RefreshCw size={14} /> Clear</button>
                          <button onClick={handleAddEvent} className="bg-accent-600 hover:bg-accent-500 text-white px-5 py-2 rounded-lg text-sm font-bold flex items-center gap-2 transition-all shadow-lg shadow-accent-900/20"><Plus size={18} /> Add Step</button>
                       </div>
                    </div>
                    <div className="relative pt-2">
                       <Timeline events={events} duration={totalDuration} onEventClick={setEditingEvent} onDeleteEvent={handleDeleteEvent} playbackTime={currentTime} />
                    </div>
                </div>

                <div className="w-full flex-1 flex flex-col bg-gray-950/20">
                    <div className="px-4 py-3 border-b border-gray-800 bg-gray-900/20 flex justify-between items-center">
                       <span className="text-[10px] text-gray-600 font-bold uppercase tracking-widest flex items-center gap-2"><FileCode size={14} /> Live Stream Buffer</span>
                       <span className="text-[9px] text-gray-700 font-mono">AUTOSYNC ENABLED</span>
                    </div>
                    <textarea value={script} onChange={(e) => setScript(e.target.value)} className="flex-1 w-full bg-transparent text-gray-600 font-mono text-xs p-6 resize-none focus:outline-none focus:text-gray-400 focus:bg-gray-950/40 transition-all leading-relaxed" spellCheck={false} placeholder="Script buffer..." />
                </div>
             </div>
           ) : (
             <div className="flex flex-col h-full bg-gray-950">
                <div className="bg-gray-900 px-6 py-3 border-b border-gray-800 text-xs text-gray-500 flex justify-between items-center">
                   <span className="font-mono flex items-center gap-2"><FileCode size={14} className="text-accent-500" /> editor.sbg</span>
                   <button onClick={() => setViewMode(ViewMode.TIMELINE)} className="text-gray-500 hover:text-white transition-colors"><Minimize2 size={14} /></button>
                </div>
                <textarea value={script} onChange={(e) => setScript(e.target.value)} className="flex-1 bg-transparent text-gray-300 font-mono p-8 outline-none resize-none text-sm leading-loose custom-scrollbar" spellCheck={false} />
             </div>
           )}
        </div>
      </main>

      <footer className="p-4 border-t border-gray-900 bg-gray-950 text-center flex items-center justify-between px-10 transition-all">
         <div className="flex items-center gap-4">
            <p className="text-[10px] text-gray-700 font-mono uppercase tracking-[0.2em]">BinauralForge Professional Suite</p>
            <div className={`w-2 h-2 rounded-full ${isPlaying ? 'bg-green-500 animate-pulse' : 'bg-gray-800'}`} />
         </div>
         <div className="flex gap-6 text-[10px] text-gray-700 font-mono uppercase tracking-widest font-bold">
            <span className="hover:text-accent-500 cursor-help transition-all">Neuro-Guide</span>
            <span className="hover:text-accent-500 cursor-help transition-all">Privacy</span>
            <span className="hover:text-accent-500 cursor-help transition-all">OpenSBaGen</span>
         </div>
      </footer>

      <EventEditor event={editingEvent} onSave={handleEventUpdate} onCancel={() => setEditingEvent(null)} />
    </div>
  );
}

export default App;

import React, { useMemo } from 'react';
import { BeatEvent } from '../types';
import { Trash2, Edit } from 'lucide-react';

interface TimelineProps {
  events: BeatEvent[];
  duration: number;
  onEventClick: (event: BeatEvent) => void;
  onDeleteEvent: (id: string) => void;
  playbackTime: number;
}

export const Timeline: React.FC<TimelineProps> = ({ events, duration, onEventClick, onDeleteEvent, playbackTime }) => {
  const widthPercent = (time: number) => (time / duration) * 100;

  const segments = useMemo(() => {
    if (events.length < 2) return [];
    const segs = [];
    for (let i = 0; i < events.length - 1; i++) {
      const start = events[i];
      const end = events[i+1];
      segs.push({ start, end });
    }
    return segs;
  }, [events]);

  return (
    <div className="relative w-full h-72 bg-gray-950/50 border border-gray-800 rounded-2xl overflow-hidden select-none mb-4 group/timeline shadow-inner">
