import React, { useEffect, useRef } from 'react';
import { audioEngine } from '../services/audioEngine';

export const Visualizer: React.FC<{ isPlaying: boolean }> = ({ isPlaying }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    let animationId: number;
    const bufferLength = audioEngine.analyserLeft?.frequencyBinCount || 256;
    const timeDataL = new Uint8Array(bufferLength);
    const timeDataR = new Uint8Array(bufferLength);
    const freqData = new Uint8Array(bufferLength);

    const draw = () => {
      const width = canvas.width;
      const height = canvas.height;

      // Subtle trails
      ctx.fillStyle = 'rgba(13, 17, 23, 0.2)';
      ctx.fillRect(0, 0, width, height);

      if (!isPlaying || !audioEngine.analyserLeft || !audioEngine.analyserRight) {
        // Idle animation: subtle breathing horizontal line
        const breathing = (Math.sin(Date.now() / 1000) + 1) / 2;
        ctx.strokeStyle = `rgba(59, 130, 246, ${0.1 + breathing * 0.1})`;
        ctx.lineWidth = 1;
        ctx.beginPath();
        ctx.moveTo(0, height / 2);
        ctx.lineTo(width, height / 2);
        ctx.stroke();
        animationId = requestAnimationFrame(draw);
        return;
      }

      audioEngine.analyserLeft.getByteTimeDomainData(timeDataL);
      audioEngine.analyserRight.getByteTimeDomainData(timeDataR);
      audioEngine.analyserLeft.getByteFrequencyData(freqData);

      // Draw Frequency Background (Lush Gradient)
      const barWidth = (width / bufferLength) * 2.5;
      let x = 0;
      for (let i = 0; i < bufferLength; i++) {
        const barHeight = (freqData[i] / 255) * height;
        const opacity = (freqData[i] / 255) * 0.2;
        ctx.fillStyle = `rgba(59, 130, 246, ${opacity})`;
        ctx.fillRect(x, height - barHeight, barWidth, barHeight);
        x += barWidth + 1;
      }

      // Draw Time-Domain Waveforms
      ctx.lineWidth = 2;
      ctx.lineJoin = 'round';
      ctx.lineCap = 'round';

      // Left Channel (Cyan)
      ctx.strokeStyle = '#22d3ee';
      ctx.shadowBlur = 10;
      ctx.shadowColor = '#22d3ee';
      ctx.beginPath();
      const sliceWidth = width / bufferLength;
      x = 0;
      for (let i = 0; i < bufferLength; i++) {
        const v = timeDataL[i] / 128.0;
        const y = (v * height) / 2;
        if (i === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
        x += sliceWidth;
      }
      ctx.stroke();

      // Right Channel (Fuchsia)
      ctx.strokeStyle = '#e879f9';
      ctx.shadowColor = '#e879f9';
      ctx.beginPath();
      x = 0;
      for (let i = 0; i < bufferLength; i++) {
        const v = timeDataR[i] / 128.0;
        const y = (v * height) / 2 + (height / 4);
        if (i === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
        x += sliceWidth;
      }
      ctx.stroke();

      ctx.shadowBlur = 0; // Reset for next frame
      animationId = requestAnimationFrame(draw);
    };

    draw();
    return () => cancelAnimationFrame(animationId);
  }, [isPlaying]);

  return (
    <div className="w-full h-40 bg-gray-950 rounded-xl overflow-hidden border border-gray-800 shadow-2xl relative">
      <canvas ref={canvasRef} width={800} height={160} className="w-full h-full block" />
      <div className="absolute inset-x-0 bottom-2 px-4 flex justify-between pointer-events-none">
          <div className="text-[8px] font-mono text-gray-700 uppercase tracking-widest">Left Spectrogram</div>
          <div className="text-[8px] font-mono text-gray-700 uppercase tracking-widest">Right Spectrogram</div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Clock, X, BellOff } from 'lucide-react';
import { TimerState } from '../types';

interface SleepTimerProps {
  onTimerEnd: () => void;
  isPlaying: boolean;
}

export const SleepTimer: React.FC<SleepTimerProps> = ({ onTimerEnd, isPlaying }) => {
  const [timer, setTimer] = useState<TimerState>({ isActive: false, remainingSeconds: 0, initialSeconds: 0 });
  const [isOpen, setIsOpen] = useState(false);

  useEffect(() => {
    let interval: number;
    if (timer.isActive && timer.remainingSeconds > 0 && isPlaying) {
      interval = window.setInterval(() => {
        setTimer(prev => ({
          ...prev,
          remainingSeconds: prev.remainingSeconds - 1
        }));
      }, 1000);
    } else if (timer.isActive && timer.remainingSeconds <= 0 && isPlaying) {
      onTimerEnd();
      setTimer({ isActive: false, remainingSeconds: 0, initialSeconds: 0 });
    }
    return () => clearInterval(interval);
  }, [timer.isActive, timer.remainingSeconds, isPlaying, onTimerEnd]);

  const startTimer = (minutes: number) => {
    setTimer({
      isActive: true,
      remainingSeconds: minutes * 60,
      initialSeconds: minutes * 60
    });
    setIsOpen(false);
  };

  const cancelTimer = () => {
    setTimer({ isActive: false, remainingSeconds: 0, initialSeconds: 0 });
    setIsOpen(false);
  };

  const formatTime = (seconds: number) => {
    const m = Math.floor(seconds / 60);
    const s = seconds % 60;
    return `${m}:${s.toString().padStart(2, '0')}`;
  };

  return (
    <div className="relative">
      <button
        onClick={() => setIsOpen(!isOpen)}
        className={`flex items-center gap-2 px-3 py-2 rounded-lg border transition-all text-sm font-medium ${
          timer.isActive 
            ? 'bg-accent-600/20 border-accent-500/50 text-accent-400' 
            : 'bg-gray-800 border-gray-700 text-gray-400 hover:text-white'
        }`}
      >
        <Clock size={16} className={timer.isActive ? 'animate-pulse' : ''} />
        {timer.isActive ? formatTime(timer.remainingSeconds) : <span className="hidden sm:inline">Sleep Timer</span>}
      </button>

      {isOpen && (
        <>
          <div className="fixed inset-0 z-40" onClick={() => setIsOpen(false)} />
          <div className="absolute bottom-full right-0 mb-2 w-48 bg-gray-900 border border-gray-800 rounded-xl shadow-2xl z-50 p-3 animate-in fade-in slide-in-from-bottom-2 duration-200">
            <div className="flex justify-between items-center mb-3 pb-2 border-b border-gray-800">
              <span className="text-[10px] font-bold text-gray-500 uppercase tracking-widest">Set Duration</span>
              <button onClick={() => setIsOpen(false)} className="text-gray-600 hover:text-white"><X size={14} /></button>
            </div>
            <div className="grid grid-cols-2 gap-2">
              {[5, 15, 30, 60].map(mins => (
                <button
                  key={mins}
                  onClick={() => startTimer(mins)}
                  className="bg-gray-800 hover:bg-gray-700 text-gray-300 py-2 rounded text-xs font-mono transition-colors border border-gray-700"
                >
                  {mins}m
                </button>
              ))}
            </div>
            {timer.isActive && (
              <button
                onClick={cancelTimer}
                className="w-full mt-3 bg-red-900/20 hover:bg-red-900/40 text-red-400 py-2 rounded text-xs font-bold flex items-center justify-center gap-2 transition-all border border-red-900/30"
              >
                <BellOff size={12} /> Cancel Timer
              </button>
            )}
          </div>
        </>
      )}
    </div>
  );
};

