import { EventEditor } from './components/EventEditor';
import { SleepTimer } from './components/SleepTimer';
import { BreathingGuide } from './components/BreathingGuide';
import { GoogleGenAI } from "@google/genai";

const DEFAULT_SCRIPT = `# Example Binaural Session
# Time  Carrier+Beat/Volume
00:00 200+10/50
01:00 200+8/50
05:00 150+4/60
10:00 150+4/0
`;

interface Preset {
  id: string;
  name: string;
  script: string;
  date: number;
}

function App() {
  const [script, setScript] = useState<string>(DEFAULT_SCRIPT);
  const [events, setEvents] = useState<BeatEvent[]>([]);
  const [isPlaying, setIsPlaying] = useState(false);
  const [viewMode, setViewMode] = useState<ViewMode>(ViewMode.TIMELINE);
  const [currentTime, setCurrentTime] = useState(0);
  const [editingEvent, setEditingEvent] = useState<BeatEvent | null>(null);
  const [aiPrompt, setAiPrompt] = useState("");
  const [isGenerating, setIsGenerating] = useState(false);
  const [volume, setVolume] = useState(50);
  const [noiseLevel, setNoiseLevel] = useState(15);
  const [noiseType, setNoiseType] = useState<NoiseType>(NoiseType.PINK);
  const [filterCutoff, setFilterCutoff] = useState(2000);
  const [breathingPattern, setBreathingPattern] = useState<BreathingPattern>(BreathingPattern.OFF);
  const [presets, setPresets] = useState<Preset[]>([]);

  const rafRef = useRef<number>(0);

  // Initial Load
  useEffect(() => {
    const saved = localStorage.getItem('bf_presets');
    if (saved) {
      try { setPresets(JSON.parse(saved)); } catch (e) {}
    }

    const urlParams = new URLSearchParams(window.location.search);
    const shared = urlParams.get('s');
    if (shared) {
      try {
        const decoded = atob(shared);
        setScript(decoded);
        window.history.replaceState({}, document.title, window.location.pathname);
      } catch (e) {}
    }
  }, []);

  // Sync Audio Engine
  useEffect(() => {
    const newEvents = parseScript(script);
    setEvents(newEvents);
    audioEngine.loadEvents(newEvents);
  }, [script]);

  const updateScriptFromEvents = useCallback((newEvents: BeatEvent[]) => {
    const sorted = [...newEvents].sort((a,b) => a.timeOffset - b.timeOffset);
    setEvents(sorted);
    setScript(generateScript(sorted));
    audioEngine.loadEvents(sorted);
  }, []);

  const handlePlayToggle = () => {
    if (isPlaying) {
      audioEngine.stop();
      setIsPlaying(false);
      cancelAnimationFrame(rafRef.current);
    } else {
      audioEngine.play(currentTime);
      setIsPlaying(true);
      const updateLoop = () => {
        setCurrentTime(audioEngine.getCurrentTime());
        rafRef.current = requestAnimationFrame(updateLoop);
      };
      updateLoop();
    }
  };

  const handleSeek = (e: React.ChangeEvent<HTMLInputElement>) => {
    const time = parseFloat(e.target.value);
    setCurrentTime(time);
    if (isPlaying) audioEngine.play(time);
  };

  const handleVolumeChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const val = parseFloat(e.target.value);
    setVolume(val);
    audioEngine.setMasterVolume(val);
  };

  const handleNoiseChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const val = parseFloat(e.target.value);
    setNoiseLevel(val);
    audioEngine.setNoiseLevel(val);
  };

  const handleFilterChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const val = parseFloat(e.target.value);
    setFilterCutoff(val);
    audioEngine.setFilterCutoff(val);
  };

  const handleNoiseTypeChange = (type: NoiseType) => {
    setNoiseType(type);
    audioEngine.setNoiseType(type);
  };

  const handleTimerEnd = () => {
    audioEngine.fadeOutAndStop(5);
    setIsPlaying(false);
    cancelAnimationFrame(rafRef.current);
  };

  const saveToPresets = () => {
    const name = prompt("Enter a name for this preset:", "Deep Meditation");
    if (!name) return;
    const newPreset: Preset = { id: `pre_${Date.now()}`, name, script, date: Date.now() };
    const updated = [newPreset, ...presets];
    setPresets(updated);
    localStorage.setItem('bf_presets', JSON.stringify(updated));
  };

  const handleShare = () => {
    const encoded = btoa(script);
    const url = `${window.location.origin}${window.location.pathname}?s=${encoded}`;
    navigator.clipboard.writeText(url).then(() => {
      alert("Shareable link copied to clipboard!");
    });
  };

  const loadPreset = (p: Preset) => {
    setScript(p.script);
    setCurrentTime(0);
    if (isPlaying) handlePlayToggle();
  };

  const deletePreset = (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    const updated = presets.filter(p => p.id !== id);
    setPresets(updated);
    localStorage.setItem('bf_presets', JSON.stringify(updated));
  };

  const handleAiGenerate = async () => {
    if (!aiPrompt.trim()) return;
    setIsGenerating(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Create an SBaGen script for: "${aiPrompt}". Format MM:SS Freq+Beat/Vol. No markdown code blocks, just raw text. Add comments explaining choice.`,
        config: { systemInstruction: "Professional Audio Engineering Expert. Binaural Entrainment Specialist." }
      });
      if (response.text) {
        setScript(response.text.replace(/```/g, '').trim());
        setAiPrompt("");
      }
    } catch (e) { console.error(e); }
    finally { setIsGenerating(false); }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (evt) => setScript(evt.target?.result as string);
    reader.readAsText(file);
    e.target.value = '';
  };

  const handleDownload = () => {
    const blob = new Blob([script], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'binaural_session.sbg';
    a.click();
    URL.revokeObjectURL(url);
  };

  // Fix: Implemented missing handleNewSequence to reset the script to default.
  const handleNewSequence = () => {
    if (window.confirm("Are you sure you want to clear the current sequence?")) {
      setScript(DEFAULT_SCRIPT);
      setCurrentTime(0);
    }
  };

  // Fix: Implemented missing handleAddEvent to insert a new beat event at current playhead.
  const handleAddEvent = () => {
    const { carrier, beat } = getCurrentValues();
    const newEvent: BeatEvent = {
      id: `evt_${Date.now()}`,
      timeOffset: currentTime,
      carrierFreq: carrier,
      beatFreq: beat,
      volume: 50,
    };
    updateScriptFromEvents([...events, newEvent]);
  };

  // Fix: Implemented missing handleDeleteEvent to remove a beat event by ID.
  const handleDeleteEvent = (id: string) => {
    updateScriptFromEvents(events.filter(e => e.id !== id));
  };

  // Fix: Implemented missing handleEventUpdate to save changes from the EventEditor.
  const handleEventUpdate = (updatedEvent: BeatEvent) => {
    const exists = events.some(e => e.id === updatedEvent.id);
    const newEvents = exists 
      ? events.map(e => e.id === updatedEvent.id ? updatedEvent : e)
      : [...events, updatedEvent];
    updateScriptFromEvents(newEvents);
    setEditingEvent(null);
  };

  const getCurrentValues = () => {
    if (events.length === 0) return { carrier: 0, beat: 0 };
    let startEvt = events[0];
    let endEvt = null;
    for (let i = 0; i < events.length; i++) {
        if (currentTime >= events[i].timeOffset) {
            startEvt = events[i];
            endEvt = events[i+1] || null;
        }
    }
    if (!endEvt) return { carrier: startEvt.carrierFreq, beat: startEvt.beatFreq };
    const progress = (currentTime - startEvt.timeOffset) / (endEvt.timeOffset - startEvt.timeOffset);
    return {
      carrier: startEvt.carrierFreq + (endEvt.carrierFreq - startEvt.carrierFreq) * progress,
      beat: startEvt.beatFreq + (endEvt.beatFreq - startEvt.beatFreq) * progress
    };
  };

  const { carrier: liveCarrier, beat: liveBeat } = getCurrentValues();
  const totalDuration = events.length > 0 ? events[events.length - 1].timeOffset + 60 : 600;

  if (viewMode === ViewMode.FOCUS) {
    return (
      <div className="fixed inset-0 bg-gray-950 flex flex-col items-center justify-center p-8 transition-all animate-in fade-in duration-700 overflow-hidden">
         <div className="absolute top-8 left-8 flex items-center gap-3 opacity-40">
            <Activity className="text-accent-500 animate-pulse" />
            <h1 className="text-xl font-bold tracking-tighter text-white">BinauralForge Focus</h1>
         </div>
         <button onClick={() => setViewMode(ViewMode.TIMELINE)} className="absolute top-8 right-8 p-3 bg-gray-900 border border-gray-800 rounded-full text-gray-500 hover:text-white transition-all hover:scale-110 active:scale-90"><Minimize2 size={24} /></button>

         <div className="w-full max-w-4xl grid grid-cols-1 lg:grid-cols-2 gap-16 items-center">
            <div className="space-y-12 text-center lg:text-left">
              <div className="space-y-4">
                <div className="text-8xl font-mono font-bold text-accent-400 tabular-nums tracking-tighter drop-shadow-[0_0_30px_rgba(59,130,246,0.3)]">
                   {liveBeat.toFixed(2)}<span className="text-xl text-gray-700 ml-2">Hz</span>
                </div>
                <div className="text-xs text-gray-500 uppercase tracking-[0.4em] font-bold">Brainwave State: Entrainment Active</div>
              </div>

              <div className="h-24 opacity-60"><Visualizer isPlaying={isPlaying} /></div>

              <div className="flex items-center justify-center lg:justify-start gap-8">
                 <button onClick={handlePlayToggle} className={`w-28 h-28 rounded-full flex items-center justify-center transition-all transform hover:scale-105 active:scale-95 ${isPlaying ? 'bg-red-500/10 text-red-400 border border-red-500/30 shadow-[0_0_40px_rgba(239,68,68,0.1)]' : 'bg-accent-600 text-white shadow-[0_0_60px_rgba(59,130,246,0.4)]'}`}>
                    {isPlaying ? <Pause size={48} fill="currentColor" /> : <Play size={48} fill="currentColor" className="ml-2" />}
                 </button>
                 <div className="flex flex-col gap-6">
                    <div className="flex items-center gap-4 w-48 text-gray-500"><Volume2 size={20} /><input type="range" min="0" max="100" value={volume} onChange={handleVolumeChange} className="w-full h-1 bg-gray-800 rounded-lg appearance-none cursor-pointer accent-accent-500" /></div>
                    <div className="flex gap-2">
                       <SleepTimer isPlaying={isPlaying} onTimerEnd={handleTimerEnd} />
                       <select value={breathingPattern} onChange={(e) => setBreathingPattern(e.target.value as BreathingPattern)} className="bg-gray-800 border-gray-700 rounded-lg px-3 py-2 text-xs text-gray-300 outline-none">
                          <option value={BreathingPattern.OFF}>Breathing: Off</option>
                          <option value={BreathingPattern.BOX}>Box (4-4-4-4)</option>
                          <option value={BreathingPattern.RELAX}>Relax (4-7-8)</option>
                          <option value={BreathingPattern.COHERENCE}>Coherence (5-5)</option>
                       </select>
                    </div>
                 </div>
              </div>
            </div>

            <div className="flex flex-col items-center justify-center">
               <BreathingGuide pattern={breathingPattern} />
            </div>
         </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-950 text-gray-200 font-sans flex flex-col selection:bg-accent-500/30">
      <header className="bg-gray-900/80 border-b border-gray-800 p-4 flex items-center justify-between sticky top-0 z-40 backdrop-blur-md">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 bg-accent-600 rounded-lg flex items-center justify-center shadow-lg shadow-accent-900/50 transition-transform hover:scale-105">
             <Activity className="text-white" />
          </div>
          <div>
            <h1 className="text-xl font-bold text-white tracking-tight">BinauralForge</h1>
            <p className="text-[10px] text-gray-500 font-mono uppercase tracking-widest">v2.5 Master Architect</p>
          </div>
        </div>

        <div className="flex items-center gap-2">
           <div className="flex bg-gray-800 rounded-lg p-1 border border-gray-700">
             <button onClick={() => setViewMode(ViewMode.TIMELINE)} className={`p-2 rounded transition-all ${viewMode === ViewMode.TIMELINE ? 'bg-gray-700 text-white shadow-inner' : 'text-gray-400 hover:text-white'}`}><Music size={18} /></button>
             <button onClick={() => setViewMode(ViewMode.SCRIPT)} className={`p-2 rounded transition-all ${viewMode === ViewMode.SCRIPT ? 'bg-gray-700 text-white shadow-inner' : 'text-gray-400 hover:text-white'}`}><FileCode size={18} /></button>
             <button onClick={() => setViewMode(ViewMode.FOCUS)} className="p-2 rounded text-gray-400 hover:text-white transition-all"><Maximize2 size={18} /></button>
           </div>
           <div className="h-6 w-px bg-gray-800 mx-1" />
           <button onClick={handleShare} className="bg-gray-800 hover:bg-gray-700 text-gray-300 p-2 rounded border border-gray-700 transition-all" title="Share Session"><Share2 size={18} /></button>
           <button onClick={saveToPresets} className="bg-gray-800 hover:bg-gray-700 text-gray-300 p-2 rounded border border-gray-700 transition-all" title="Save Preset"><Bookmark size={18} /></button>
           <button onClick={handleDownload} className="bg-accent-600 hover:bg-accent-500 text-white px-3 py-2 rounded border border-accent-500 transition-all text-sm font-bold flex items-center gap-2"><Save size={16} /><span className="hidden sm:inline">Export</span></button>
        </div>
      </header>

      <main className="flex-1 flex flex-col p-6 gap-6 max-w-7xl mx-auto w-full">
        <div className="grid grid-cols-1 lg:grid-cols-4 gap-6">
           <div className="lg:col-span-3 space-y-4">
              <Visualizer isPlaying={isPlaying} />

              <div className="bg-gray-900 rounded-xl p-4 border border-gray-800 shadow-2xl flex flex-col md:flex-row items-center gap-6">
                 <button onClick={handlePlayToggle} className={`w-16 h-16 rounded-full flex-none flex items-center justify-center transition-all transform hover:scale-105 active:scale-95 ${isPlaying ? 'bg-red-500 hover:bg-red-600' : 'bg-green-500 hover:bg-green-600'} text-white shadow-xl`}>
                    {isPlaying ? <Pause size={28} fill="currentColor" /> : <Play size={28} fill="currentColor" className="ml-1" />}
                 </button>

                 <div className="flex-1 w-full md:w-auto px-2">
                    <div className="flex justify-between text-[10px] font-mono text-gray-500 mb-2 uppercase tracking-tighter">
                       <span>{new Date(currentTime * 1000).toISOString().substr(14, 5)}</span>
                       <span className="text-gray-400">Master Playhead</span>
                       <span>{new Date(totalDuration * 1000).toISOString().substr(14, 5)}</span>
                    </div>
                    <input type="range" min="0" max={totalDuration} value={currentTime} onChange={handleSeek} className="w-full h-2 bg-gray-800 rounded-lg appearance-none cursor-pointer accent-accent-500" />
                 </div>

                 <div className="flex-none grid grid-cols-2 gap-x-6 gap-y-3 p-4 bg-gray-850/50 rounded-xl border border-gray-800">
                    <div className="flex items-center gap-3 text-gray-400">
                       <Volume2 size={14} />
                       <input type="range" min="0" max="100" value={volume} onChange={handleVolumeChange} className="w-24 h-1 bg-gray-700 rounded-lg appearance-none cursor-pointer accent-gray-400" />
                    </div>
                    <div className="flex items-center gap-3 text-gray-400">
                       <Sliders size={14} />
                       <input type="range" min="200" max="8000" value={filterCutoff} onChange={handleFilterChange} className="w-24 h-1 bg-gray-700 rounded-lg appearance-none cursor-pointer accent-accent-600" />
                    </div>
                    <div className="flex items-center gap-3 text-gray-400">
                       <Wind size={14} />
                       <input type="range" min="0" max="50" value={noiseLevel} onChange={handleNoiseChange} className="w-24 h-1 bg-gray-700 rounded-lg appearance-none cursor-pointer accent-gray-400" />
                    </div>
                    <div className="flex gap-1">
                        {[NoiseType.WHITE, NoiseType.PINK, NoiseType.BROWN].map(t => (
                          <button key={t} onClick={() => handleNoiseTypeChange(t)} className={`flex-1 text-[8px] font-bold py-1 px-1 rounded transition-all ${noiseType === t ? 'bg-accent-600 text-white' : 'bg-gray-700 text-gray-500'}`}>{t.charAt(0)}</button>
                        ))}
                    </div>
                 </div>
              </div>
           </div>

           <div className="bg-gray-900 rounded-xl p-5 border border-gray-800 shadow-xl flex flex-col gap-4 overflow-hidden h-[340px] lg:h-auto">
              <div className="flex justify-between items-center border-b border-gray-800 pb-3">
                 <h3 className="text-gray-500 uppercase tracking-widest text-[10px] font-bold flex items-center gap-2"><Bookmark size={12}/> Library</h3>
                 <SleepTimer isPlaying={isPlaying} onTimerEnd={handleTimerEnd} />
              </div>
              <div className="flex-1 overflow-y-auto space-y-2 pr-1 custom-scrollbar">
                 {presets.map(p => (
                    <div key={p.id} onClick={() => loadPreset(p)} className="group flex items-center justify-between bg-gray-850 hover:bg-gray-800 p-3 rounded-lg border border-gray-800 cursor-pointer transition-all hover:border-accent-500/30">
                       <div className="truncate flex-1 pr-2">
                          <div className="text-xs font-bold truncate text-gray-300">{p.name}</div>
                          <div className="text-[9px] text-gray-600 font-mono italic">{new Date(p.date).toLocaleDateString()}</div>
                       </div>
                       <button onClick={(e) => deletePreset(p.id, e)} className="p-1.5 opacity-0 group-hover:opacity-100 text-gray-600 hover:text-red-400 transition-all"><Trash2 size={12} /></button>
                    </div>
                 ))}
                 {presets.length === 0 && <div className="text-[10px] text-gray-700 text-center py-12 border-2 border-dashed border-gray-800 rounded-xl">Session library empty</div>}
              </div>
           </div>
        </div>

        <div className="bg-gradient-to-r from-gray-900 to-gray-850 rounded-xl p-1 border border-gray-700/50 shadow-inner group">
           <div className="flex flex-col sm:flex-row gap-2 p-2">
              <div className="flex-1 relative">
                 <input type="text" placeholder="AI Synth: e.g. 'Delta sleep protocol with pink noise background starting at 180Hz'" className="w-full bg-gray-950 border border-gray-700 rounded-lg px-4 py-3 text-gray-200 focus:ring-2 focus:ring-accent-500 outline-none text-sm placeholder-gray-600 font-mono transition-all" value={aiPrompt} onChange={(e) => setAiPrompt(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && handleAiGenerate()} />
                 <Wand2 className="absolute right-4 top-1/2 -translate-y-1/2 text-gray-700 group-hover:text-accent-500 transition-colors" size={18} />
              </div>
              <button onClick={handleAiGenerate} disabled={isGenerating || !aiPrompt.trim()} className="bg-accent-600 hover:bg-accent-500 disabled:opacity-50 text-white px-8 py-3 rounded-lg text-sm font-bold flex items-center justify-center gap-2 transition-all shadow-xl shadow-accent-900/30">
                 {isGenerating ? <span className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin" /> : <Wand2 size={16} />}
                 <span>{isGenerating ? 'Synthesizing...' : 'Forge Session'}</span>
              </button>
           </div>
        </div>

        <div className="flex-1 min-h-[500px] bg-gray-900 rounded-xl border border-gray-800 shadow-2xl overflow-hidden flex flex-col relative">
           {viewMode === ViewMode.TIMELINE ? (
             <div className="flex flex-col h-full">
                <div className="w-full p-6 flex-none border-b border-gray-800 bg-gray-900/50">
                    <div className="flex justify-between items-start mb-6">
                       <div className="flex gap-4">
                          <div className="p-4 bg-gray-950 rounded-xl border border-gray-800 shadow-inner min-w-[150px]">
                             <span className="text-[10px] text-gray-600 uppercase font-bold tracking-widest block mb-1">Entrainment</span>
                             <span className="text-4xl font-mono font-bold text-accent-400 tabular-nums leading-none">{liveBeat.toFixed(2)}<span className="text-sm text-gray-700 ml-1 font-sans font-normal">Hz</span></span>
                          </div>
                          <div className="p-4 bg-gray-950 rounded-xl border border-gray-800 shadow-inner min-w-[120px]">
                             <span className="text-[10px] text-gray-600 uppercase font-bold tracking-widest block mb-1">Carrier</span>
                             <span className="text-2xl font-mono text-gray-500 tabular-nums leading-none">{liveCarrier.toFixed(0)}<span className="text-xs text-gray-700 ml-1 font-sans font-normal">Hz</span></span>
                          </div>
                       </div>
                       <div className="flex gap-2">
                          <button onClick={handleNewSequence} className="bg-gray-800 hover:bg-red-900/20 hover:text-red-400 text-gray-500 px-4 py-2 rounded-lg text-xs font-bold flex items-center gap-2 transition-all border border-gray-700"><RefreshCw size={14} /> Clear</button>
                          <button onClick={handleAddEvent} className="bg-accent-600 hover:bg-accent-500 text-white px-5 py-2 rounded-lg text-xs font-bold flex items-center gap-2 transition-all shadow-lg shadow-accent-900/20"><Plus size={18} /> New Event</button>
                       </div>
                    </div>
                    <div className="relative pt-2">
                       <Timeline events={events} duration={totalDuration} onEventClick={setEditingEvent} onDeleteEvent={handleDeleteEvent} playbackTime={currentTime} />
                    </div>
                </div>

                <div className="w-full flex-1 flex flex-col bg-gray-950/30">
                    <div className="px-4 py-3 border-b border-gray-800 bg-gray-900/20 flex justify-between items-center">
                       <span className="text-[10px] text-gray-600 font-bold uppercase tracking-[0.2em] flex items-center gap-2"><FileCode size={14} className="text-accent-500" /> Script Stream (SBaGen)</span>
                       <span className="text-[8px] text-gray-800 font-mono">ENCODING: UTF-8</span>
                    </div>
                    <textarea value={script} onChange={(e) => setScript(e.target.value)} className="flex-1 w-full bg-transparent text-gray-600 font-mono text-xs p-8 resize-none focus:outline-none focus:text-gray-400 focus:bg-gray-950/40 transition-all leading-relaxed custom-scrollbar" spellCheck={false} placeholder="Enter your SBaGen instructions here..." />
                </div>
             </div>
           ) : (
             <div className="flex flex-col h-full bg-gray-950">
                <div className="bg-gray-900 px-6 py-4 border-b border-gray-800 text-xs text-gray-500 flex justify-between items-center">
                   <span className="font-mono flex items-center gap-2 text-accent-500"><FileCode size={16} /> master_sequence.sbg</span>
                   <div className="flex gap-4">
                      <label className="cursor-pointer hover:text-white transition-colors flex items-center gap-2"><Upload size={14}/> Import<input type="file" className="hidden" onChange={handleFileUpload}/></label>
                      <button onClick={() => setViewMode(ViewMode.TIMELINE)} className="text-gray-600 hover:text-white transition-colors"><Minimize2 size={14} /></button>
                   </div>
                </div>
                <textarea value={script} onChange={(e) => setScript(e.target.value)} className="flex-1 bg-transparent text-gray-400 font-mono p-12 outline-none resize-none text-sm leading-loose custom-scrollbar selection:bg-accent-500/20" spellCheck={false} />
             </div>
           )}
        </div>
      </main>

      <footer className="p-4 border-t border-gray-900 bg-gray-950 flex items-center justify-between px-10 transition-all opacity-60 hover:opacity-100">
         <div className="flex items-center gap-4">
            <p className="text-[10px] text-gray-700 font-mono uppercase tracking-[0.3em] font-bold">Forge Core Active</p>
            <div className={`w-2 h-2 rounded-full ${isPlaying ? 'bg-green-500 animate-pulse shadow-[0_0_10px_rgba(34,197,94,0.5)]' : 'bg-gray-800'}`} />
         </div>
         <div className="flex gap-8 text-[9px] text-gray-700 font-mono uppercase tracking-widest font-bold">
            <span className="hover:text-accent-500 cursor-help transition-all">Documentation</span>
            <span className="hover:text-accent-500 cursor-help transition-all">Neuro-Acoustics API</span>
            <span className="hover:text-accent-500 cursor-help transition-all">GitHub</span>
         </div>
      </footer>

      <EventEditor event={editingEvent} onSave={handleEventUpdate} onCancel={() => setEditingEvent(null)} />
    </div>
  );
}

export default App;

import { BeatEvent, NoiseType } from '../types';

class BinauralAudioEngine {
  private ctx: AudioContext | null = null;
  private masterGain: GainNode | null = null;

  private oscLeft: OscillatorNode | null = null;
  private oscRight: OscillatorNode | null = null;
  private pannerLeft: StereoPannerNode | null = null;
  private pannerRight: StereoPannerNode | null = null;

  private noiseNode: ScriptProcessorNode | null = null;
  private noiseGain: GainNode | null = null;
  private noiseFilter: BiquadFilterNode | null = null;
  private currentNoiseType: NoiseType = NoiseType.PINK;

  private lfo: OscillatorNode | null = null;
  private lfoGain: GainNode | null = null;

  private breathingMod: GainNode | null = null;

  public analyserLeft: AnalyserNode | null = null;
  public analyserRight: AnalyserNode | null = null;

  private isRunning: boolean = false;
  private events: BeatEvent[] = [];
  private playbackStartTime: number = 0;
  private pausedAt: number = 0;
  private masterVolume: number = 0.5;
  private noiseLevel: number = 0.15;
  private filterCutoff: number = 2000;

  constructor() {}

  init() {
    if (this.ctx) return;
    this.ctx = new (window.AudioContext || (window as any).webkitAudioContext)();

    this.masterGain = this.ctx.createGain();
    this.masterGain.connect(this.ctx.destination);
    this.masterGain.gain.value = this.masterVolume;

    this.breathingMod = this.ctx.createGain();
    this.breathingMod.gain.value = 1.0;
    this.breathingMod.connect(this.masterGain);

    this.analyserLeft = this.ctx.createAnalyser();
    this.analyserRight = this.ctx.createAnalyser();
    this.analyserLeft.fftSize = 1024;
    this.analyserRight.fftSize = 1024;

    this.setupNoise();
    this.setupLFO();
  }

  private setupLFO() {
    if (!this.ctx || !this.breathingMod) return;
    this.lfo = this.ctx.createOscillator();
    this.lfoGain = this.ctx.createGain();
    this.lfo.frequency.value = 0.08; 
    this.lfoGain.gain.value = 0.03;
    this.lfo.connect(this.lfoGain);
    this.lfo.start();
  }

  private setupNoise() {
    if (!this.ctx || !this.breathingMod) return;

    const bufferSize = 4096;
    let b0, b1, b2, b3, b4, b5, b6;
    b0 = b1 = b2 = b3 = b4 = b5 = b6 = 0.0;
    let lastOut = 0.0;

    const node = this.ctx.createScriptProcessor(bufferSize, 1, 1);
    node.onaudioprocess = (e) => {
      const output = e.outputBuffer.getChannelData(0);
      for (let i = 0; i < bufferSize; i++) {
        const white = Math.random() * 2 - 1;

        if (this.currentNoiseType === NoiseType.WHITE) {
          output[i] = white * 0.1;
        } else if (this.currentNoiseType === NoiseType.PINK) {
          b0 = 0.99886 * b0 + white * 0.0555179;
          b1 = 0.99332 * b1 + white * 0.0750759;
          b2 = 0.96900 * b2 + white * 0.1538520;
          b3 = 0.86650 * b3 + white * 0.3104856;
          b4 = 0.55000 * b4 + white * 0.5329522;
          b5 = -0.7616 * b5 - white * 0.0168980;
          output[i] = b0 + b1 + b2 + b3 + b4 + b5 + b6 + white * 0.5362;
          output[i] *= 0.11;
          b6 = white * 0.115926;
        } else if (this.currentNoiseType === NoiseType.BROWN) {
          output[i] = (lastOut + (0.02 * white)) / 1.02;
          lastOut = output[i];
          output[i] *= 3.5;
        } else {
          output[i] = 0;
        }
      }
    };

    this.noiseFilter = this.ctx.createBiquadFilter();
    this.noiseFilter.type = 'lowpass';
    this.noiseFilter.frequency.value = this.filterCutoff;
    this.noiseFilter.Q.value = 1.0;

    this.noiseGain = this.ctx.createGain();
    this.noiseGain.gain.value = this.currentNoiseType === NoiseType.OFF ? 0 : this.noiseLevel;

    node.connect(this.noiseFilter);
    this.noiseFilter.connect(this.noiseGain);
    this.noiseGain.connect(this.breathingMod);
    this.noiseNode = node;
  }

  setNoiseType(type: NoiseType) {
    this.currentNoiseType = type;
    if (this.noiseGain && this.ctx) {
      const target = type === NoiseType.OFF ? 0 : this.noiseLevel;
      this.noiseGain.gain.setTargetAtTime(target, this.ctx.currentTime, 0.1);
    }
  }

  setFilterCutoff(hz: number) {
    this.filterCutoff = hz;
    if (this.noiseFilter && this.ctx) {
      this.noiseFilter.frequency.setTargetAtTime(hz, this.ctx.currentTime, 0.1);
    }
  }

  setMasterVolume(percent: number) {
    this.masterVolume = Math.max(0, Math.min(1, percent / 100));
    if (this.masterGain && this.ctx) {
      this.masterGain.gain.setTargetAtTime(this.masterVolume, this.ctx.currentTime, 0.05);
    }
  }

  setNoiseLevel(percent: number) {
    this.noiseLevel = Math.max(0, Math.min(1, percent / 100));
    if (this.noiseGain && this.ctx && this.currentNoiseType !== NoiseType.OFF) {
      this.noiseGain.gain.setTargetAtTime(this.noiseLevel, this.ctx.currentTime, 0.1);
    }
  }

  setBreathingIntensity(intensity: number) {
    // Subtle ducking of the whole mix (0.0 to 1.0 intensity)
    if (this.breathingMod && this.ctx) {
      const target = 1.0 - (intensity * 0.15); // max 15% ducking
      this.breathingMod.gain.setTargetAtTime(target, this.ctx.currentTime, 0.1);
    }
  }

  private clearOscillators() {
    [this.oscLeft, this.oscRight].forEach(osc => {
      if (osc) {
        try { osc.stop(); } catch(e) {}
        osc.disconnect();
      }
    });
    this.oscLeft = null;
    this.oscRight = null;
  }

  private createOscillators(startTime: number) {
    if (!this.ctx || !this.breathingMod) return;
    this.clearOscillators();

    this.oscLeft = this.ctx.createOscillator();
    this.pannerLeft = this.ctx.createStereoPanner();
    this.pannerLeft.pan.value = -1;

    this.oscRight = this.ctx.createOscillator();
    this.pannerRight = this.ctx.createStereoPanner();
    this.pannerRight.pan.value = 1;

    this.oscLeft.connect(this.pannerLeft);
    if(this.analyserLeft) this.pannerLeft.connect(this.analyserLeft);
    this.pannerLeft.connect(this.breathingMod);

    this.oscRight.connect(this.pannerRight);
    if(this.analyserRight) this.pannerRight.connect(this.analyserRight);
    this.pannerRight.connect(this.breathingMod);

    const now = this.ctx.currentTime;

    this.events.forEach((evt) => {
      const evtTime = now + (evt.timeOffset - startTime);
      const leftFreq = evt.carrierFreq - (evt.beatFreq / 2);
      const rightFreq = evt.carrierFreq + (evt.beatFreq / 2);

      if (evtTime <= now) {
        this.oscLeft?.frequency.setValueAtTime(leftFreq, now);
        this.oscRight?.frequency.setValueAtTime(rightFreq, now);
      } else {
        this.oscLeft?.frequency.linearRampToValueAtTime(leftFreq, evtTime);
        this.oscRight?.frequency.linearRampToValueAtTime(rightFreq, evtTime);
      }
    });

    this.oscLeft.start(now);
    this.oscRight.start(now);
  }

  loadEvents(events: BeatEvent[]) {
    this.events = [...events].sort((a, b) => a.timeOffset - b.timeOffset);
    if (this.isRunning) {
      this.createOscillators(this.getCurrentTime());
    }
  }

  play(offset: number = 0) {
    if (!this.ctx) this.init();
    if (this.ctx?.state === 'suspended') this.ctx.resume();

    if (this.masterGain && this.ctx) {
      this.masterGain.gain.setTargetAtTime(this.masterVolume, this.ctx.currentTime, 0.1);
    }

    this.pausedAt = offset;
    this.createOscillators(offset);
    this.isRunning = true;
    this.playbackStartTime = this.ctx!.currentTime - offset;
  }

  stop() {
    this.clearOscillators();
    this.isRunning = false;
  }

  fadeOutAndStop(duration: number = 5) {
    if (!this.ctx || !this.masterGain) {
      this.stop();
      return;
    }
    const now = this.ctx.currentTime;
    this.masterGain.gain.linearRampToValueAtTime(0, now + duration);
    setTimeout(() => {
      if (this.isRunning) this.stop();
    }, duration * 1000 + 100);
  }

  getCurrentTime(): number {
    if (!this.isRunning || !this.ctx) return this.pausedAt;
    return this.ctx.currentTime - this.playbackStartTime;
  }

  getIsRunning(): boolean {
    return this.isRunning;
  }
}

export const audioEngine = new BinauralAudioEngine();

import React, { useState, useEffect, useRef } from 'react';
import { BreathingPattern, BreathingState } from '../types';

interface BreathingGuideProps {
  pattern: BreathingPattern;
  onPhaseProgress?: (progress: number) => void;
}

const PATTERNS: Record<BreathingPattern, number[]> = {
  [BreathingPattern.OFF]: [0, 0, 0, 0],
  [BreathingPattern.BOX]: [4, 4, 4, 4], // In, Hold, Out, Hold
  [BreathingPattern.RELAX]: [4, 7, 8, 0], // In, Hold, Out, Hold
  [BreathingPattern.COHERENCE]: [5, 0, 5, 0], // In, Hold, Out, Hold
};

export const BreathingGuide: React.FC<BreathingGuideProps> = ({ pattern, onPhaseProgress }) => {
  const [state, setState] = useState<BreathingState>({
    pattern,
    phase: 'inhale',
    progress: 0,
  });

  const requestRef = useRef<number>(0);
  const startTimeRef = useRef<number>(0);

  useEffect(() => {
    if (pattern === BreathingPattern.OFF) {
      cancelAnimationFrame(requestRef.current);
      if (onPhaseProgress) onPhaseProgress(0);
      return;
    }

    const animate = (time: number) => {
      if (!startTimeRef.current) startTimeRef.current = time;
      const elapsed = (time - startTimeRef.current) / 1000;

      const config = PATTERNS[pattern];
      const totalCycle = config.reduce((a, b) => a + b, 0);
      const cycleTime = elapsed % totalCycle;

      let currentPhase: BreathingState['phase'] = 'inhale';
      let phaseStart = 0;
      let phaseDuration = config[0];

      if (cycleTime < config[0]) {
        currentPhase = 'inhale';
        phaseDuration = config[0];
      } else if (cycleTime < config[0] + config[1]) {
        currentPhase = 'hold_in';
        phaseStart = config[0];
        phaseDuration = config[1];
      } else if (cycleTime < config[0] + config[1] + config[2]) {
        currentPhase = 'exhale';
        phaseStart = config[0] + config[1];
        phaseDuration = config[2];
      } else {
        currentPhase = 'hold_out';
        phaseStart = config[0] + config[1] + config[2];
        phaseDuration = config[3];
      }

      const progress = (cycleTime - phaseStart) / phaseDuration;
      const safeProgress = isNaN(progress) ? 0 : progress;

      // Map progress to intensity for audio ducking
      // We want the most ducking (intensity = 1.0) at peak inhale
      let intensity = 0;
      if (currentPhase === 'inhale') intensity = safeProgress;
      else if (currentPhase === 'hold_in') intensity = 1.0;
      else if (currentPhase === 'exhale') intensity = 1.0 - safeProgress;
      else intensity = 0;

      if (onPhaseProgress) onPhaseProgress(intensity);

      setState({
        pattern,
        phase: currentPhase,
        progress: safeProgress,
      });

      requestRef.current = requestAnimationFrame(animate);
    };

    requestRef.current = requestAnimationFrame(animate);
    return () => cancelAnimationFrame(requestRef.current);
  }, [pattern, onPhaseProgress]);

  if (pattern === BreathingPattern.OFF) return null;

  // Calculate visual scale
  let scale = 1;
  if (state.phase === 'inhale') scale = 1 + state.progress * 0.5;
  else if (state.phase === 'hold_in') scale = 1.5;
  else if (state.phase === 'exhale') scale = 1.5 - state.progress * 0.5;
  else scale = 1;

  const phaseLabels = {
    inhale: 'Inhale',
    hold_in: 'Hold',
    exhale: 'Exhale',
    hold_out: 'Hold',
  };

  return (
    <div className="flex flex-col items-center justify-center gap-6 animate-in fade-in duration-500">
      <div className="relative flex items-center justify-center w-48 h-48">
        {/* Pulsing ring */}
        <div 
          className="absolute inset-0 rounded-full border-2 border-accent-500/20 transition-transform duration-100 ease-linear"
          style={{ transform: `scale(${scale * 1.2})` }}
        />
        {/* Inner circle */}
        <div 
          className="absolute inset-0 rounded-full bg-gradient-to-br from-accent-500/40 to-accent-600/10 backdrop-blur-md shadow-[0_0_30px_rgba(59,130,246,0.2)] transition-transform duration-100 ease-linear flex flex-col items-center justify-center border border-accent-500/20"
          style={{ transform: `scale(${scale})` }}
        >
          <span className="text-white font-bold tracking-widest uppercase text-[10px] drop-shadow-md">
            {phaseLabels[state.phase]}
          </span>
        </div>
      </div>
      <div className="flex flex-col items-center gap-1">
        <span className="text-[10px] text-gray-500 uppercase tracking-[0.3em] font-bold">Respiration Sync</span>
        <div className="w-32 h-1 bg-gray-800 rounded-full overflow-hidden">
           <div 
             className="h-full bg-accent-500 transition-all duration-100 ease-linear" 
             style={{ width: `${state.progress * 100}%` }} 
           />
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { 
  Play, Pause, Upload, Plus, FileCode, Activity, Music, 
  Volume2, Save, Wand2, RefreshCw, Bookmark, Trash2, Wind,
  Share2, Maximize2, Minimize2, Settings2, Sliders, Timer,
  ExternalLink, Search, Zap, Moon, Brain, Sun
} from 'lucide-react';
import { BeatEvent, ViewMode, NoiseType, BreathingPattern } from './types';
import { parseScript, generateScript } from './services/parser';
import { audioEngine } from './services/audioEngine';
import { Timeline } from './components/Timeline';
import { Visualizer } from './components/Visualizer';
import { EventEditor } from './components/EventEditor';
import { SleepTimer } from './components/SleepTimer';
import { BreathingGuide } from './components/BreathingGuide';
import { GoogleGenAI } from "@google/genai";

const DEFAULT_SCRIPT = `# Example Binaural Session
# Time  Carrier+Beat/Volume
00:00 200+10/50
01:00 200+8/50
05:00 150+4/60
10:00 150+4/0
`;

const STANDARD_PROTOCOLS = [
  { name: 'Deep Delta Sleep', icon: Moon, script: "00:00 180+2.5/50\n10:00 180+1.0/40\n30:00 180+1.0/0" },
  { name: 'Intense Alpha Flow', icon: Zap, script: "00:00 210+10.0/60\n15:00 210+12.0/60\n45:00 210+8.0/30" },
  { name: 'Gamma Sharp Focus', icon: Brain, script: "00:00 240+40.0/40\n10:00 240+40.0/50\n30:00 240+40.0/0" },
  { name: 'Theta Insight', icon: Sun, script: "00:00 190+6.0/50\n05:00 190+4.5/50\n20:00 190+4.5/0" },
];

interface Preset {
  id: string;
  name: string;
  script: string;
  date: number;
}

interface GroundingSource {
  title: string;
  uri: string;
}

function App() {
  const [script, setScript] = useState<string>(DEFAULT_SCRIPT);
  const [events, setEvents] = useState<BeatEvent[]>([]);
  const [isPlaying, setIsPlaying] = useState(false);
  const [viewMode, setViewMode] = useState<ViewMode>(ViewMode.TIMELINE);
  const [currentTime, setCurrentTime] = useState(0);
  const [editingEvent, setEditingEvent] = useState<BeatEvent | null>(null);
  const [aiPrompt, setAiPrompt] = useState("");
  const [isGenerating, setIsGenerating] = useState(false);
  const [volume, setVolume] = useState(50);
  const [noiseLevel, setNoiseLevel] = useState(15);
  const [noiseType, setNoiseType] = useState<NoiseType>(NoiseType.PINK);
  const [filterCutoff, setFilterCutoff] = useState(2000);
  const [breathingPattern, setBreathingPattern] = useState<BreathingPattern>(BreathingPattern.OFF);
  const [presets, setPresets] = useState<Preset[]>([]);
  const [sources, setSources] = useState<GroundingSource[]>([]);

  const rafRef = useRef<number>(0);

  // Persistence: Auto-load & Shared
  useEffect(() => {
    const savedPresets = localStorage.getItem('bf_presets');
    if (savedPresets) {
      try { setPresets(JSON.parse(savedPresets)); } catch (e) {}
    }

    const lastSession = localStorage.getItem('bf_current_script');
    if (lastSession && script === DEFAULT_SCRIPT) {
      setScript(lastSession);
    }

    const urlParams = new URLSearchParams(window.location.search);
    const shared = urlParams.get('s');
    if (shared) {
      try {
        const decoded = atob(shared);
        setScript(decoded);
        window.history.replaceState({}, document.title, window.location.pathname);
      } catch (e) {}
    }
  }, []);

  // Persistence: Auto-save
  useEffect(() => {
    localStorage.setItem('bf_current_script', script);
  }, [script]);

  // Sync Audio Engine
  useEffect(() => {
    const newEvents = parseScript(script);
    setEvents(newEvents);
    audioEngine.loadEvents(newEvents);
  }, [script]);

  const updateScriptFromEvents = useCallback((newEvents: BeatEvent[]) => {
    const sorted = [...newEvents].sort((a,b) => a.timeOffset - b.timeOffset);
    setEvents(sorted);
    const newScript = generateScript(sorted);
    setScript(newScript);
    audioEngine.loadEvents(sorted);
  }, []);

  const handlePlayToggle = () => {
    if (isPlaying) {
      audioEngine.stop();
      setIsPlaying(false);
      cancelAnimationFrame(rafRef.current);
    } else {
      audioEngine.play(currentTime);
      setIsPlaying(true);
      const updateLoop = () => {
        setCurrentTime(audioEngine.getCurrentTime());
        rafRef.current = requestAnimationFrame(updateLoop);
      };
      updateLoop();
    }
  };

  const handleSeek = (e: React.ChangeEvent<HTMLInputElement>) => {
    const time = parseFloat(e.target.value);
    setCurrentTime(time);
    if (isPlaying) audioEngine.play(time);
  };

  const handleVolumeChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const val = parseFloat(e.target.value);
    setVolume(val);
    audioEngine.setMasterVolume(val);
  };

  const handleNoiseChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const val = parseFloat(e.target.value);
    setNoiseLevel(val);
    audioEngine.setNoiseLevel(val);
  };

  const handleFilterChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const val = parseFloat(e.target.value);
    setFilterCutoff(val);
    audioEngine.setFilterCutoff(val);
  };

  const handleNoiseTypeChange = (type: NoiseType) => {
    setNoiseType(type);
    audioEngine.setNoiseType(type);
  };

  const handleTimerEnd = () => {
    audioEngine.fadeOutAndStop(5);
    setIsPlaying(false);
    cancelAnimationFrame(rafRef.current);
  };

  const saveToPresets = () => {
    const name = prompt("Enter a name for this preset:", "Deep Meditation");
    if (!name) return;
    const newPreset: Preset = { id: `pre_${Date.now()}`, name, script, date: Date.now() };
    const updated = [newPreset, ...presets];
    setPresets(updated);
    localStorage.setItem('bf_presets', JSON.stringify(updated));
  };

  const handleShare = () => {
    const encoded = btoa(script);
    const url = `${window.location.origin}${window.location.pathname}?s=${encoded}`;
    navigator.clipboard.writeText(url).then(() => {
      alert("Shareable link copied to clipboard!");
    });
  };

  const loadPreset = (p: Preset | { name: string, script: string }) => {
    setScript(p.script);
    setCurrentTime(0);
    if (isPlaying) handlePlayToggle();
  };

  const deletePreset = (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    const updated = presets.filter(p => p.id !== id);
    setPresets(updated);
    localStorage.setItem('bf_presets', JSON.stringify(updated));
  };

  const handleAiGenerate = async () => {
    if (!aiPrompt.trim()) return;
    setIsGenerating(true);
    setSources([]);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Research the scientific literature for optimal binaural frequencies and carriers for: "${aiPrompt}". Then create an SBaGen script. Format MM:SS Freq+Beat/Vol. Raw text only, no code blocks.`,
        config: { 
          systemInstruction: "You are a world-class neuro-acoustics researcher and audio engineer. Use Search to verify actual scientific data.",
          tools: [{ googleSearch: {} }]
        }
      });

      if (response.text) {
        setScript(response.text.replace(/```/g, '').trim());
        setAiPrompt("");

        // Extract grounding sources if available
        const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
        if (groundingChunks) {
          const newSources = groundingChunks
            .filter((chunk: any) => chunk.web)
            .map((chunk: any) => ({
              title: chunk.web.title || "Research Source",
              uri: chunk.web.uri
            }));
          setSources(newSources);
        }
      }
    } catch (e) { console.error(e); }
    finally { setIsGenerating(false); }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (evt) => setScript(evt.target?.result as string);
    reader.readAsText(file);
    e.target.value = '';
  };

  const handleDownload = () => {
    const blob = new Blob([script], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'binaural_session.sbg';
    a.click();
    URL.revokeObjectURL(url);
  };

  const handleNewSequence = () => {
    if (window.confirm("Are you sure you want to clear the current sequence?")) {
      setScript(DEFAULT_SCRIPT);
      setCurrentTime(0);
    }
  };

  const handleAddEvent = () => {
    const { carrier, beat } = getCurrentValues();
    const newEvent: BeatEvent = {
      id: `evt_${Date.now()}`,
      timeOffset: currentTime,
      carrierFreq: carrier,
      beatFreq: beat,
      volume: 50,
    };
    updateScriptFromEvents([...events, newEvent]);
  };

  const handleDeleteEvent = (id: string) => {
    updateScriptFromEvents(events.filter(e => e.id !== id));
  };

  const handleEventUpdate = (updatedEvent: BeatEvent) => {
    const exists = events.some(e => e.id === updatedEvent.id);
    const newEvents = exists 
      ? events.map(e => e.id === updatedEvent.id ? updatedEvent : e)
      : [...events, updatedEvent];
    updateScriptFromEvents(newEvents);
    setEditingEvent(null);
  };

  const getCurrentValues = () => {
    if (events.length === 0) return { carrier: 0, beat: 0 };
    let startEvt = events[0];
    let endEvt = null;
    for (let i = 0; i < events.length; i++) {
        if (currentTime >= events[i].timeOffset) {
            startEvt = events[i];
            endEvt = events[i+1] || null;
        }
    }
    if (!endEvt) return { carrier: startEvt.carrierFreq, beat: startEvt.beatFreq };
    const progress = (currentTime - startEvt.timeOffset) / (endEvt.timeOffset - startEvt.timeOffset);
    return {
      carrier: startEvt.carrierFreq + (endEvt.carrierFreq - startEvt.carrierFreq) * progress,
      beat: startEvt.beatFreq + (endEvt.beatFreq - startEvt.beatFreq) * progress
    };
  };

  const { carrier: liveCarrier, beat: liveBeat } = getCurrentValues();
  const totalDuration = events.length > 0 ? events[events.length - 1].timeOffset + 60 : 600;

  if (viewMode === ViewMode.FOCUS) {
    return (
      <div className="fixed inset-0 bg-gray-950 flex flex-col items-center justify-center p-8 transition-all animate-in fade-in duration-700 overflow-hidden">
         <div className="absolute top-8 left-8 flex items-center gap-3 opacity-40">
            <Activity className="text-accent-500 animate-pulse" />
            <h1 className="text-xl font-bold tracking-tighter text-white">BinauralForge Focus</h1>
         </div>
         <button onClick={() => setViewMode(ViewMode.TIMELINE)} className="absolute top-8 right-8 p-3 bg-gray-900 border border-gray-800 rounded-full text-gray-500 hover:text-white transition-all hover:scale-110 active:scale-90 shadow-2xl"><Minimize2 size={24} /></button>

         <div className="w-full max-w-5xl grid grid-cols-1 lg:grid-cols-2 gap-16 items-center">
            <div className="space-y-12 text-center lg:text-left">
              <div className="space-y-4">
                <div className="text-8xl font-mono font-bold text-accent-400 tabular-nums tracking-tighter drop-shadow-[0_0_40px_rgba(59,130,246,0.3)]">
                   {liveBeat.toFixed(2)}<span className="text-xl text-gray-700 ml-2">Hz</span>
                </div>
                <div className="text-xs text-gray-500 uppercase tracking-[0.4em] font-bold">Resonant Entropy: Entrainment Field Active</div>
              </div>

              <div className="h-24 opacity-60"><Visualizer isPlaying={isPlaying} /></div>

              <div className="flex items-center justify-center lg:justify-start gap-12">
                 <button onClick={handlePlayToggle} className={`w-32 h-32 rounded-full flex items-center justify-center transition-all transform hover:scale-105 active:scale-95 ${isPlaying ? 'bg-red-500/10 text-red-400 border border-red-500/30 shadow-[0_0_50px_rgba(239,68,68,0.1)]' : 'bg-accent-600 text-white shadow-[0_0_70px_rgba(59,130,246,0.4)]'}`}>
                    {isPlaying ? <Pause size={56} fill="currentColor" /> : <Play size={56} fill="currentColor" className="ml-2" />}
                 </button>
                 <div className="flex flex-col gap-8">
                    <div className="flex items-center gap-4 w-56 text-gray-500">
                       <Volume2 size={24} />
                       <input type="range" min="0" max="100" value={volume} onChange={handleVolumeChange} className="w-full h-1 bg-gray-800 rounded-lg appearance-none cursor-pointer accent-accent-500" />
                    </div>
                    <div className="flex gap-4">
                       <SleepTimer isPlaying={isPlaying} onTimerEnd={handleTimerEnd} />
                       <select value={breathingPattern} onChange={(e) => setBreathingPattern(e.target.value as BreathingPattern)} className="bg-gray-900 border border-gray-700 rounded-xl px-4 py-3 text-xs text-gray-300 outline-none shadow-xl focus:ring-2 focus:ring-accent-500 transition-all">
                          <option value={BreathingPattern.OFF}>Breathing: Off</option>
                          <option value={BreathingPattern.BOX}>Box (4-4-4-4)</option>
                          <option value={BreathingPattern.RELAX}>Relax (4-7-8)</option>
                          <option value={BreathingPattern.COHERENCE}>Coherence (5-5)</option>
                       </select>
                    </div>
                 </div>
              </div>
            </div>

            <div className="flex flex-col items-center justify-center">
               <BreathingGuide pattern={breathingPattern} onPhaseProgress={(val) => audioEngine.setBreathingIntensity(val)} />
            </div>
         </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-950 text-gray-200 font-sans flex flex-col selection:bg-accent-500/30">
      <header className="bg-gray-900/90 border-b border-gray-800 p-4 flex items-center justify-between sticky top-0 z-40 backdrop-blur-xl">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 bg-accent-600 rounded-xl flex items-center justify-center shadow-lg shadow-accent-900/30 transition-transform hover:scale-105">
             <Activity className="text-white" />
          </div>
          <div>
            <h1 className="text-xl font-bold text-white tracking-tight">BinauralForge</h1>
            <p className="text-[10px] text-gray-500 font-mono uppercase tracking-[0.2em]">Neural Architect v2.5</p>
          </div>
        </div>

        <div className="flex items-center gap-2">
           <div className="flex bg-gray-800/50 rounded-xl p-1 border border-gray-700/50">
             <button onClick={() => setViewMode(ViewMode.TIMELINE)} className={`p-2.5 rounded-lg transition-all ${viewMode === ViewMode.TIMELINE ? 'bg-gray-700 text-white shadow-lg' : 'text-gray-400 hover:text-white'}`}><Music size={18} /></button>
             <button onClick={() => setViewMode(ViewMode.SCRIPT)} className={`p-2.5 rounded-lg transition-all ${viewMode === ViewMode.SCRIPT ? 'bg-gray-700 text-white shadow-lg' : 'text-gray-400 hover:text-white'}`}><FileCode size={18} /></button>
             <button onClick={() => setViewMode(ViewMode.FOCUS)} className="p-2.5 rounded-lg text-gray-400 hover:text-white transition-all"><Maximize2 size={18} /></button>
           </div>
           <div className="h-6 w-px bg-gray-800 mx-1" />
           <button onClick={handleShare} className="bg-gray-800/80 hover:bg-gray-700 text-gray-300 p-2.5 rounded-xl border border-gray-700/50 transition-all hover:scale-105 active:scale-95" title="Share Session"><Share2 size={18} /></button>
           <button onClick={saveToPresets} className="bg-gray-800/80 hover:bg-gray-700 text-gray-300 p-2.5 rounded-xl border border-gray-700/50 transition-all hover:scale-105 active:scale-95" title="Save Preset"><Bookmark size={18} /></button>
           <button onClick={handleDownload} className="bg-accent-600 hover:bg-accent-500 text-white px-4 py-2.5 rounded-xl border border-accent-500 shadow-xl shadow-accent-900/20 transition-all text-sm font-bold flex items-center gap-2 hover:scale-105 active:scale-95"><Save size={16} /><span className="hidden sm:inline">Export SBG</span></button>
        </div>
      </header>

      <main className="flex-1 flex flex-col p-6 gap-6 max-w-7xl mx-auto w-full animate-in fade-in slide-in-from-bottom-2 duration-500">
        <div className="grid grid-cols-1 lg:grid-cols-4 gap-6">
           <div className="lg:col-span-3 space-y-4">
              <Visualizer isPlaying={isPlaying} />

              <div className="bg-gray-900/80 rounded-2xl p-6 border border-gray-800 shadow-2xl flex flex-col md:flex-row items-center gap-8 backdrop-blur-sm">
                 <button onClick={handlePlayToggle} className={`w-20 h-20 rounded-full flex-none flex items-center justify-center transition-all transform hover:scale-105 active:scale-95 ${isPlaying ? 'bg-red-500 hover:bg-red-600 shadow-red-900/40' : 'bg-green-500 hover:bg-green-600 shadow-green-900/40'} text-white shadow-2xl`}>
                    {isPlaying ? <Pause size={36} fill="currentColor" /> : <Play size={36} fill="currentColor" className="ml-1" />}
                 </button>

                 <div className="flex-1 w-full md:w-auto px-2">
                    <div className="flex justify-between text-[10px] font-mono text-gray-500 mb-3 uppercase tracking-widest">
                       <span className="text-accent-500">{new Date(currentTime * 1000).toISOString().substr(14, 5)}</span>
                       <span className="text-gray-600">Sequence Progress</span>
                       <span>{new Date(totalDuration * 1000).toISOString().substr(14, 5)}</span>
                    </div>
                    <input type="range" min="0" max={totalDuration} value={currentTime} onChange={handleSeek} className="w-full h-2 bg-gray-800 rounded-lg appearance-none cursor-pointer accent-accent-500" />
                 </div>

                 <div className="flex-none grid grid-cols-2 gap-x-8 gap-y-4 p-5 bg-gray-950/40 rounded-2xl border border-gray-800/50">
                    <div className="flex items-center gap-3 text-gray-500">
                       <Volume2 size={16} />
                       <input type="range" min="0" max="100" value={volume} onChange={handleVolumeChange} className="w-28 h-1 bg-gray-800 rounded-lg appearance-none cursor-pointer accent-gray-400" />
                    </div>
                    <div className="flex items-center gap-3 text-gray-500">
                       <Sliders size={16} />
                       <input type="range" min="200" max="8000" value={filterCutoff} onChange={handleFilterChange} className="w-28 h-1 bg-gray-800 rounded-lg appearance-none cursor-pointer accent-accent-600" />
                    </div>
                    <div className="flex items-center gap-3 text-gray-500">
                       <Wind size={16} />
                       <input type="range" min="0" max="50" value={noiseLevel} onChange={handleNoiseChange} className="w-28 h-1 bg-gray-800 rounded-lg appearance-none cursor-pointer accent-gray-400" />
                    </div>
                    <div className="flex gap-1.5">
                        {[NoiseType.WHITE, NoiseType.PINK, NoiseType.BROWN].map(t => (
                          <button key={t} onClick={() => handleNoiseTypeChange(t)} className={`flex-1 text-[9px] font-bold py-1 px-2 rounded-lg transition-all ${noiseType === t ? 'bg-accent-600 text-white shadow-lg shadow-accent-900/20' : 'bg-gray-800 text-gray-500 hover:text-gray-300'}`}>{t.charAt(0)}</button>
                        ))}
                    </div>
                 </div>
              </div>
           </div>

           <div className="flex flex-col gap-6 h-full">
              <div className="bg-gray-900/80 rounded-2xl p-5 border border-gray-800 shadow-xl flex flex-col gap-4 flex-1 overflow-hidden backdrop-blur-sm">
                 <div className="flex justify-between items-center border-b border-gray-800 pb-3">
                    <h3 className="text-gray-500 uppercase tracking-widest text-[10px] font-bold flex items-center gap-2"><Activity size={12}/> Standard Protocols</h3>
                 </div>
                 <div className="grid grid-cols-1 gap-2">
                    {STANDARD_PROTOCOLS.map(proto => (
                       <button key={proto.name} onClick={() => loadPreset(proto)} className="flex items-center gap-3 p-3 bg-gray-850/50 hover:bg-accent-950/30 rounded-xl border border-gray-800/50 text-left transition-all hover:border-accent-500/30 group">
                          <proto.icon size={16} className="text-accent-500 group-hover:scale-110 transition-transform" />
                          <span className="text-xs font-semibold text-gray-300 group-hover:text-white">{proto.name}</span>
                       </button>
                    ))}
                 </div>
              </div>

              <div className="bg-gray-900/80 rounded-2xl p-5 border border-gray-800 shadow-xl flex flex-col gap-4 h-[240px] overflow-hidden backdrop-blur-sm">
                 <div className="flex justify-between items-center border-b border-gray-800 pb-3">
                    <h3 className="text-gray-500 uppercase tracking-widest text-[10px] font-bold flex items-center gap-2"><Bookmark size={12}/> User Library</h3>
                    <SleepTimer isPlaying={isPlaying} onTimerEnd={handleTimerEnd} />
                 </div>
                 <div className="flex-1 overflow-y-auto space-y-2 pr-1 custom-scrollbar">
                    {presets.map(p => (
                       <div key={p.id} onClick={() => loadPreset(p)} className="group flex items-center justify-between bg-gray-850/50 hover:bg-gray-800 p-3 rounded-xl border border-gray-800/50 cursor-pointer transition-all hover:border-accent-500/30">
                          <div className="truncate flex-1 pr-2">
                             <div className="text-xs font-bold truncate text-gray-300">{p.name}</div>
                             <div className="text-[9px] text-gray-600 font-mono italic">{new Date(p.date).toLocaleDateString()}</div>
                          </div>
                          <button onClick={(e) => deletePreset(p.id, e)} className="p-1.5 opacity-0 group-hover:opacity-100 text-gray-600 hover:text-red-400 transition-all"><Trash2 size={12} /></button>
                       </div>
                    ))}
                    {presets.length === 0 && <div className="text-[10px] text-gray-700 text-center py-10 border-2 border-dashed border-gray-800/50 rounded-2xl">Library empty</div>}
                 </div>
              </div>
           </div>
        </div>

        <div className="bg-gradient-to-r from-gray-900 via-gray-850 to-gray-900 rounded-2xl p-1 border border-gray-700/30 shadow-2xl group relative overflow-hidden">
           {isGenerating && (
             <div className="absolute inset-0 bg-accent-600/5 animate-pulse pointer-events-none" />
           )}
           <div className="flex flex-col sm:flex-row gap-3 p-3 relative z-10">
              <div className="flex-1 relative">
                 <input 
                    type="text" 
                    placeholder="Forge with AI: e.g. 'Deep meditation protocol using research-backed Theta frequencies'" 
                    className="w-full bg-gray-950 border border-gray-800 rounded-xl px-5 py-4 text-gray-100 focus:ring-2 focus:ring-accent-500 outline-none text-sm placeholder-gray-600 font-mono transition-all pr-12 shadow-inner" 
                    value={aiPrompt} 
                    onChange={(e) => setAiPrompt(e.target.value)} 
                    onKeyDown={(e) => e.key === 'Enter' && handleAiGenerate()} 
                 />
                 <Search className="absolute right-5 top-1/2 -translate-y-1/2 text-gray-700 group-hover:text-accent-500 transition-colors" size={20} />
              </div>
              <button 
                onClick={handleAiGenerate} 
                disabled={isGenerating || !aiPrompt.trim()} 
                className="bg-accent-600 hover:bg-accent-500 disabled:opacity-50 text-white px-10 py-4 rounded-xl text-sm font-bold flex items-center justify-center gap-3 transition-all shadow-2xl shadow-accent-900/40 hover:scale-[1.02] active:scale-[0.98]"
              >
                 {isGenerating ? <RefreshCw className="w-5 h-5 animate-spin" /> : <Wand2 size={20} />}
                 <span>{isGenerating ? 'Analyzing Scientific Data...' : 'Research & Forge'}</span>
              </button>
           </div>

           {sources.length > 0 && (
             <div className="px-6 py-4 bg-gray-950/50 border-t border-gray-800/50 flex flex-wrap gap-4 animate-in slide-in-from-top-2 duration-300">
                <span className="text-[10px] text-gray-600 uppercase font-bold tracking-widest flex items-center gap-2"><Zap size={12} className="text-yellow-500" /> Grounding Evidence:</span>
                {sources.map((s, idx) => (
                   <a key={idx} href={s.uri} target="_blank" rel="noopener noreferrer" className="text-[10px] text-accent-500 hover:text-accent-400 font-mono flex items-center gap-1.5 transition-colors underline decoration-accent-500/30">
                      <ExternalLink size={10} /> {s.title}
                   </a>
                ))}
             </div>
           )}
        </div>

        <div className="flex-1 min-h-[500px] bg-gray-900/90 rounded-2xl border border-gray-800 shadow-2xl overflow-hidden flex flex-col relative backdrop-blur-sm">
           {viewMode === ViewMode.TIMELINE ? (
             <div className="flex flex-col h-full animate-in fade-in duration-300">
                <div className="w-full p-8 flex-none border-b border-gray-800/50 bg-gray-900/30">
                    <div className="flex justify-between items-start mb-8">
                       <div className="flex gap-6">
                          <div className="p-5 bg-gray-950/80 rounded-2xl border border-gray-800 shadow-2xl min-w-[160px] group/val transition-all hover:border-accent-500/30">
                             <span className="text-[10px] text-gray-600 uppercase font-bold tracking-widest block mb-2">Entrainment Target</span>
                             <span className="text-5xl font-mono font-bold text-accent-400 tabular-nums tracking-tighter leading-none group-hover/val:text-accent-300 transition-colors">
                               {liveBeat.toFixed(2)}<span className="text-base text-gray-700 ml-1 font-sans font-normal">Hz</span>
                             </span>
                          </div>
                          <div className="p-5 bg-gray-950/80 rounded-2xl border border-gray-800 shadow-2xl min-w-[140px] transition-all hover:border-gray-700">
                             <span className="text-[10px] text-gray-600 uppercase font-bold tracking-widest block mb-2">Carrier Frequency</span>
                             <span className="text-3xl font-mono text-gray-500 tabular-nums leading-none">
                               {liveCarrier.toFixed(0)}<span className="text-xs text-gray-700 ml-1 font-sans font-normal">Hz</span>
                             </span>
                          </div>
                       </div>
                       <div className="flex gap-3">
                          <button onClick={handleNewSequence} className="bg-gray-800/50 hover:bg-red-900/20 hover:text-red-400 text-gray-500 px-6 py-3 rounded-xl text-xs font-bold flex items-center gap-2 transition-all border border-gray-700/50 shadow-lg"><RefreshCw size={14} /> Reset Space</button>
                          <button onClick={handleAddEvent} className="bg-accent-600 hover:bg-accent-500 text-white px-8 py-3 rounded-xl text-xs font-bold flex items-center gap-2 transition-all shadow-2xl shadow-accent-900/30 hover:scale-105 active:scale-95"><Plus size={18} /> Append Step</button>
                       </div>
                    </div>
                    <div className="relative pt-2">
                       <Timeline events={events} duration={totalDuration} onEventClick={setEditingEvent} onDeleteEvent={handleDeleteEvent} playbackTime={currentTime} />
                    </div>
                </div>

                <div className="w-full flex-1 flex flex-col bg-gray-950/20">
                    <div className="px-6 py-4 border-b border-gray-800/50 bg-gray-900/30 flex justify-between items-center">
                       <span className="text-[10px] text-gray-600 font-bold uppercase tracking-[0.2em] flex items-center gap-2"><FileCode size={14} className="text-accent-500" /> Workspace Buffer (SBaGen Stream)</span>
                       <div className="flex items-center gap-3">
                          <div className="w-2 h-2 rounded-full bg-green-500 shadow-[0_0_8px_rgba(34,197,94,0.5)]" />
                          <span className="text-[8px] text-gray-700 font-mono">AUTOSAVE ENGAGED</span>
                       </div>
                    </div>
                    <textarea value={script} onChange={(e) => setScript(e.target.value)} className="flex-1 w-full bg-transparent text-gray-600 font-mono text-xs p-10 resize-none focus:outline-none focus:text-gray-400 focus:bg-gray-950/40 transition-all leading-relaxed custom-scrollbar" spellCheck={false} placeholder="Live script editor..." />
                </div>
             </div>
           ) : (
             <div className="flex flex-col h-full bg-gray-950 animate-in fade-in duration-300">
                <div className="bg-gray-900 px-8 py-4 border-b border-gray-800 text-xs text-gray-500 flex justify-between items-center">
                   <span className="font-mono flex items-center gap-2 text-accent-500"><FileCode size={16} /> master_architecture.sbg</span>
                   <div className="flex gap-6">
                      <label className="cursor-pointer hover:text-white transition-colors flex items-center gap-2 font-bold uppercase tracking-widest text-[10px]"><Upload size={14}/> Import Script<input type="file" className="hidden" onChange={handleFileUpload}/></label>
                      <button onClick={() => setViewMode(ViewMode.TIMELINE)} className="text-gray-600 hover:text-white transition-colors"><Minimize2 size={16} /></button>
                   </div>
                </div>
                <textarea value={script} onChange={(e) => setScript(e.target.value)} className="flex-1 bg-transparent text-gray-400 font-mono p-12 outline-none resize-none text-sm leading-loose custom-scrollbar selection:bg-accent-500/20" spellCheck={false} />
             </div>
           )}
        </div>
      </main>

      <footer className="p-6 border-t border-gray-900/50 bg-gray-950 flex items-center justify-between px-12 transition-all opacity-80 hover:opacity-100">
         <div className="flex items-center gap-6">
            <div className="flex flex-col">
               <p className="text-[10px] text-gray-600 font-mono uppercase tracking-[0.4em] font-bold">Forge Core Active</p>
               <p className="text-[8px] text-gray-800 font-mono mt-1">LATENCY: LOW | SAMPLE RATE: 44.1kHz</p>
            </div>
            <div className={`w-2.5 h-2.5 rounded-full ${isPlaying ? 'bg-green-500 animate-pulse shadow-[0_0_15px_rgba(34,197,94,0.6)]' : 'bg-gray-800'}`} />
         </div>
         <div className="flex gap-10 text-[9px] text-gray-700 font-mono uppercase tracking-widest font-bold">
            <span className="hover:text-accent-500 cursor-help transition-all border-b border-transparent hover:border-accent-500 pb-1">Documentation</span>
            <span className="hover:text-accent-500 cursor-help transition-all border-b border-transparent hover:border-accent-500 pb-1">Neuro-Acoustic API</span>
            <span className="hover:text-accent-500 cursor-help transition-all border-b border-transparent hover:border-accent-500 pb-1">GitHub Repo</span>
         </div>
      </footer>

      <EventEditor event={editingEvent} onSave={handleEventUpdate} onCancel={() => setEditingEvent(null)} />
    </div>
  );
}

export default App;
